select public.upsert_bank_question($json${"id":"hist3-easy-001","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":3,"verse_start":24,"verse_end":25,"texts":{"pt":{"prompt":"Quando duas mulheres disputavam um menino, o que mandou Salomão trazer?","bible_ref":"1 Reis 3:24-25","verse_text":"E disse o rei: Trazei-me uma espada. E trouxeram ao rei uma espada. Em seguida o rei disse: Parti por meio o menino vivo, e dai a metade à uma, e a outra metade à outra."},"fr":{"prompt":"Quand deux femmes se disputaient un enfant, que fit apporter Salomon ?","bible_ref":"1 Rois 3:24-25","verse_text":"Puis il ajouta: Apportez-moi une épée. On apporta une épée devant le roi. Et le roi dit: Coupez en deux l’enfant qui vit, et donnez-en la moitié à l’une et la moitié à l’autre."},"en":{"prompt":"When two women argued over a child, what did Solomon ask to be brought?","bible_ref":"1 Kings 3:24-25","verse_text":"And the king said, Bring me a sword. And they brought a sword before the king. And the king said, Divide the living child in two, and give half to the one, and half to the other."},"es":{"prompt":"Cuando dos mujeres se disputaban un niño, ¿qué mandó traer Salomón?","bible_ref":"1 Reyes 3:24-25","verse_text":"Y dijo el rey: Traedme un cuchillo. Y trajeron al rey un cuchillo. En seguida el rey dijo: Partid por medio el niño vivo, y dad la mitad á la una, y la otra mitad á la otra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma espada"},"fr":{"text":"Une épée"},"en":{"text":"A sword"},"es":{"text":"Un cuchillo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma balança"},"fr":{"text":"Une balance"},"en":{"text":"A pair of scales"},"es":{"text":"Una balanza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um livro"},"fr":{"text":"Un livre"},"en":{"text":"A book"},"es":{"text":"Un libro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um cesto"},"fr":{"text":"Un panier"},"en":{"text":"A basket"},"es":{"text":"Una cesta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-002","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":10,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Quem ouviu falar da fama de Salomão e veio pô-lo à prova com perguntas?","bible_ref":"1 Reis 10:1","verse_text":"E ouvindo a rainha de Sabá a fama de Salomão no nome do SENHOR, veio a provar-lhe com perguntas."},"fr":{"prompt":"Qui apprit la renommée de Salomon et vint l’éprouver par des énigmes ?","bible_ref":"1 Rois 10:1","verse_text":"La reine de Séba apprit la renommée que possédait Salomon, à la gloire de l’Éternel, et elle vint pour l’éprouver par des énigmes."},"en":{"prompt":"Who heard of the fame of Solomon and came to prove him with hard questions?","bible_ref":"1 Kings 10:1","verse_text":"And when the queen of Sheba heard of the fame of Solomon concerning the name of the LORD, she came to prove him with hard questions."},"es":{"prompt":"¿Quién oyó la fama de Salomón y vino a probarle con preguntas?","bible_ref":"1 Reyes 10:1","verse_text":"Y oyendo la reina de Seba la fama de Salomón en el nombre de Jehová, vino á probarle con preguntas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A rainha de Sabá"},"fr":{"text":"La reine de Séba"},"en":{"text":"The queen of Sheba"},"es":{"text":"La reina de Seba"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A rainha Jezabel"},"fr":{"text":"La reine Jézabel"},"en":{"text":"Queen Jezebel"},"es":{"text":"La reina Jezabel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A rainha Vasti"},"fr":{"text":"La reine Vasthi"},"en":{"text":"Queen Vashti"},"es":{"text":"La reina Vasthi"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mical, filha de Saul"},"fr":{"text":"Mical, fille de Saül"},"en":{"text":"Michal, Saul’s daughter"},"es":{"text":"Michâl, hija de Saúl"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-003","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":17,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Quando Elias clamou ao SENHOR pelo filho da viúva, o que aconteceu ao menino?","bible_ref":"1 Reis 17:22","verse_text":"E o SENHOR ouviu a voz de Elias, e a alma do menino voltou a suas entranhas, e reviveu."},"fr":{"prompt":"Quand Élie implora l’Éternel pour le fils de la veuve, qu’arriva-t-il à l’enfant ?","bible_ref":"1 Rois 17:22","verse_text":"L’Éternel écouta la voix d’Élie, et l’âme de l’enfant revint au-dedans de lui, et il fut rendu à la vie."},"en":{"prompt":"When Elijah cried to the LORD for the widow’s son, what happened to the child?","bible_ref":"1 Kings 17:22","verse_text":"And the LORD heard the voice of Elijah; and the soul of the child came into him again, and he revived."},"es":{"prompt":"Cuando Elías clamó a Jehová por el hijo de la viuda, ¿qué le pasó al niño?","bible_ref":"1 Reyes 17:22","verse_text":"Y Jehová oyó la voz de Elías, y el alma del niño volvió á sus entrañas, y revivió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Voltou a viver"},"fr":{"text":"Il revint à la vie"},"en":{"text":"He revived"},"es":{"text":"Revivió"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Adormeceu"},"fr":{"text":"Il s’endormit"},"en":{"text":"He fell asleep"},"es":{"text":"Se durmió"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Fugiu para o deserto"},"fr":{"text":"Il s’enfuit au désert"},"en":{"text":"He ran away to the wilderness"},"es":{"text":"Huyó al desierto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tornou-se profeta"},"fr":{"text":"Il devint prophète"},"en":{"text":"He became a prophet"},"es":{"text":"Se hizo profeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-004","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":18,"verse_start":34,"verse_end":34,"texts":{"pt":{"prompt":"Quantas vezes mandou Elias derramar água sobre o holocausto?","bible_ref":"1 Reis 18:34","verse_text":"E disse: Enchei quatro cântaros de água, e derramai-a sobre o holocausto e sobre a lenha. E disse: Fazei-o outra vez; e outra vez o fizeram. Disse ainda: Fazei-o a terceira vez; e fizeram-no a terceira vez."},"fr":{"prompt":"Combien de fois Élie fit-il verser de l’eau sur l’holocauste ?","bible_ref":"1 Rois 18:34","verse_text":"Puis il dit: Remplissez d’eau quatre cruches, et versez-les sur l’holocauste et sur le bois. Il dit: Faites-le une seconde fois. Et ils le firent une seconde fois. Il dit: Faites-le une troisième fois. Et ils le firent une troisième fois."},"en":{"prompt":"How many times did Elijah have water poured on the sacrifice?","bible_ref":"1 Kings 18:34","verse_text":"And he said, Do it the second time. And they did it the second time. And he said, Do it the third time. And they did it the third time."},"es":{"prompt":"¿Cuántas veces mandó Elías derramar agua sobre el holocausto?","bible_ref":"1 Reyes 18:34","verse_text":"Y dijo: Henchid cuatro cántaros de agua, y derramadla sobre el holocausto y sobre la leña. Y dijo: Hacedlo otra vez; y otra vez lo hicieron. Dijo aún: Hacedlo la tercera vez; é hiciéronlo la tercera vez."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três vezes"},"fr":{"text":"Trois fois"},"en":{"text":"Three times"},"es":{"text":"Tres veces"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sete vezes"},"fr":{"text":"Sept fois"},"en":{"text":"Seven times"},"es":{"text":"Siete veces"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Duas vezes"},"fr":{"text":"Deux fois"},"en":{"text":"Two times"},"es":{"text":"Dos veces"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze vezes"},"fr":{"text":"Douze fois"},"en":{"text":"Twelve times"},"es":{"text":"Doce veces"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-005","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":18,"verse_start":44,"verse_end":44,"texts":{"pt":{"prompt":"À sétima vez, o que viu o servo de Elias a subir do mar?","bible_ref":"1 Reis 18:44","verse_text":"E à sétima vez disse: Eu vejo uma pequena nuvem como a palma da mão de um homem, que sobe do mar. E ele disse: Vai, e dize a Acabe: Unge e desce, porque a chuva não te interrompa."},"fr":{"prompt":"À la septième fois, que vit le serviteur d’Élie s’élever de la mer ?","bible_ref":"1 Rois 18:44","verse_text":"A la septième fois, il dit: Voici un petit nuage qui s’élève de la mer, et qui est comme la paume de la main d’un homme. Élie dit: Monte, et dis à Achab: Attelle et descends, afin que la pluie ne t’arrête pas."},"en":{"prompt":"At the seventh time, what did Elijah’s servant see arise out of the sea?","bible_ref":"1 Kings 18:44","verse_text":"And it came to pass at the seventh time, that he said, Behold, there ariseth a little cloud out of the sea, like a man’s hand. And he said, Go up, say unto Ahab, Prepare thy chariot, and get thee down, that the rain stop thee not."},"es":{"prompt":"A la séptima vez, ¿qué vio el criado de Elías subir del mar?","bible_ref":"1 Reyes 18:44","verse_text":"Y á la séptima vez dijo: Yo veo una pequeña nube como la palma de la mano de un hombre, que sube de la mar. Y él dijo: Ve, y di á Achâb: Unce y desciende, porque la lluvia no te ataje."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma pequena nuvem como a mão de um homem"},"fr":{"text":"Un petit nuage comme la main d’un homme"},"en":{"text":"A little cloud like a man’s hand"},"es":{"text":"Una pequeña nube como la mano de un hombre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um grande peixe"},"fr":{"text":"Un grand poisson"},"en":{"text":"A great fish"},"es":{"text":"Un gran pez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um navio"},"fr":{"text":"Un navire"},"en":{"text":"A ship"},"es":{"text":"Un navío"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um arco-íris"},"fr":{"text":"Un arc-en-ciel"},"en":{"text":"A rainbow"},"es":{"text":"Un arco iris"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-006","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":19,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Quando Elias acordou no deserto, o que encontrou à sua cabeceira?","bible_ref":"1 Reis 19:6","verse_text":"Então ele olhou, e eis que a sua cabeceira uma torta cozida sobre as ascuas, e um vaso de água: e comeu e bebeu e voltou-se a dormir."},"fr":{"prompt":"Quand Élie se réveilla dans le désert, que trouva-t-il à son chevet ?","bible_ref":"1 Rois 19:6","verse_text":"Il regarda, et il y avait à son chevet un gâteau cuit sur des pierres chauffées et une cruche d’eau. Il mangea et but, puis se recoucha."},"en":{"prompt":"When Elijah woke in the wilderness, what was at his head?","bible_ref":"1 Kings 19:6","verse_text":"And he looked, and, behold, there was a cake baken on the coals, and a cruse of water at his head. And he did eat and drink, and laid him down again."},"es":{"prompt":"Cuando Elías despertó en el desierto, ¿qué halló a su cabecera?","bible_ref":"1 Reyes 19:6","verse_text":"Entonces él miró, y he aquí á su cabecera una torta cocida sobre las ascuas, y un vaso de agua: y comió y bebió, y volvióse á dormir."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um bolo cozido e um vaso de água"},"fr":{"text":"Un gâteau cuit et une cruche d’eau"},"en":{"text":"A cake baken on the coals and a cruse of water"},"es":{"text":"Una torta cocida y un vaso de agua"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um corvo com carne"},"fr":{"text":"Un corbeau avec de la viande"},"en":{"text":"A raven with meat"},"es":{"text":"Un cuervo con carne"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um manto novo"},"fr":{"text":"Un manteau neuf"},"en":{"text":"A new mantle"},"es":{"text":"Un manto nuevo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma espada"},"fr":{"text":"Une épée"},"en":{"text":"A sword"},"es":{"text":"Una espada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-007","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":6,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Porque não se ouviam martelos nem machados enquanto se edificava o templo?","bible_ref":"1 Reis 6:7","verse_text":"E a casa quando se edificou, fabricaram-na de pedras que traziam já acabadas; de tal maneira que quando a edificavam, nem martelos nem machados se ouviram na casa, nem nenhum outro instrumento de ferro."},"fr":{"prompt":"Pourquoi n’entendait-on ni marteau ni hache pendant qu’on bâtissait le temple ?","bible_ref":"1 Rois 6:7","verse_text":"Lorsqu’on bâtit la maison, on se servit de pierres toutes taillées, et ni marteau, ni hache, ni aucun instrument de fer, ne furent entendus dans la maison pendant qu’on la construisait."},"en":{"prompt":"Why was no hammer nor axe heard while the temple was being built?","bible_ref":"1 Kings 6:7","verse_text":"And the house, when it was in building, was built of stone made ready before it was brought thither: so that there was neither hammer nor axe nor any tool of iron heard in the house, while it was in building."},"es":{"prompt":"¿Por qué no se oían martillos ni hachas mientras se edificaba el templo?","bible_ref":"1 Reyes 6:7","verse_text":"Y la casa cuando se edificó, fabricáronla de piedras que traían ya acabadas; de tal manera que cuando la edificaban, ni martillos ni hachas se oyeron en la casa, ni ningún otro instrumento de hierro."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As pedras já vinham acabadas"},"fr":{"text":"Les pierres étaient déjà taillées"},"en":{"text":"The stones were made ready before"},"es":{"text":"Las piedras ya venían acabadas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Só se trabalhava de noite"},"fr":{"text":"On ne travaillait que la nuit"},"en":{"text":"It was built only at night"},"es":{"text":"Solo se trabajaba de noche"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Era todo feito de madeira"},"fr":{"text":"Il était tout en bois"},"en":{"text":"It was all made of wood"},"es":{"text":"Era todo de madera"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O rei proibia o barulho"},"fr":{"text":"Le roi interdisait le bruit"},"en":{"text":"The king forbade any noise"},"es":{"text":"El rey prohibía el ruido"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-008","type":"choice","level":"easy","testament":"ot","book":"2KI","chapter":2,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Que coisa de Elias levantou Eliseu, depois de ela ter caído?","bible_ref":"2 Reis 2:13","verse_text":"Levantou logo o manto de Elias que se lhe havia caído, e voltou, e parou-se à beira do Jordão."},"fr":{"prompt":"Qu’est-ce qu’Élisée releva, après qu’Élie l’eut laissé tomber ?","bible_ref":"2 Rois 2:13","verse_text":"et il releva le manteau qu’Élie avait laissé tomber. Puis il retourna, et s’arrêta au bord du Jourdain;"},"en":{"prompt":"What did Elisha take up that had fallen from Elijah?","bible_ref":"2 Kings 2:13","verse_text":"He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;"},"es":{"prompt":"¿Qué cosa de Elías alzó Eliseo, después de habérsele caído?","bible_ref":"2 Reyes 2:13","verse_text":"Alzó luego el manto de Elías que se le había caído, y volvió, y paróse á la orilla del Jordán."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O manto"},"fr":{"text":"Le manteau"},"en":{"text":"His mantle"},"es":{"text":"El manto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O cajado"},"fr":{"text":"Le bâton"},"en":{"text":"His staff"},"es":{"text":"El báculo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A espada"},"fr":{"text":"L’épée"},"en":{"text":"His sword"},"es":{"text":"La espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A coroa"},"fr":{"text":"La couronne"},"en":{"text":"His crown"},"es":{"text":"La corona"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-009","type":"choice","level":"easy","testament":"ot","book":"2KI","chapter":4,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"O que quis uma mulher preparar para o profeta Eliseu, para quando ele passasse?","bible_ref":"2 Reis 4:10","verse_text":"Eu te rogo que faças uma pequena câmara de paredes, e ponhamos nela cama, e mesa, e cadeira, e candelabro, para que quando vier a nós, se recolha nela."},"fr":{"prompt":"Que voulut préparer une femme pour le prophète Élisée, pour quand il passerait ?","bible_ref":"2 Rois 4:10","verse_text":"Faisons une petite chambre haute avec des murs, et mettons-y pour lui un lit, une table, un siège et un chandelier, afin qu’il s’y retire quand il viendra chez nous."},"en":{"prompt":"What did a woman want to make for the prophet Elisha, for when he came by?","bible_ref":"2 Kings 4:10","verse_text":"Let us make a little chamber, I pray thee, on the wall; and let us set for him there a bed, and a table, and a stool, and a candlestick: and it shall be, when he cometh to us, that he shall turn in thither."},"es":{"prompt":"¿Qué quiso preparar una mujer para el profeta Eliseo, para cuando pasara?","bible_ref":"2 Reyes 4:10","verse_text":"Yo te ruego que hagas una pequeña cámara de paredes, y pongamos en ella cama, y mesa, y silla, y candelero, para que cuando viniere á nosotros, se recoja en ella."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma pequena câmara com cama e mesa"},"fr":{"text":"Une petite chambre avec un lit et une table"},"en":{"text":"A little chamber with a bed and a table"},"es":{"text":"Una pequeña cámara con cama y mesa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma tenda no jardim"},"fr":{"text":"Une tente dans le jardin"},"en":{"text":"A tent in the garden"},"es":{"text":"Una tienda en el jardín"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um altar de pedras"},"fr":{"text":"Un autel de pierres"},"en":{"text":"An altar of stones"},"es":{"text":"Un altar de piedras"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um barco para o rio"},"fr":{"text":"Une barque pour le fleuve"},"en":{"text":"A boat for the river"},"es":{"text":"Una barca para el río"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-010","type":"choice","level":"easy","testament":"ot","book":"2KI","chapter":4,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Quando o azeite encheu as vasilhas, o que disse Eliseu à mulher?","bible_ref":"2 Reis 4:7","verse_text":"Veio ela logo, e contou-o ao homem de Deus, o qual disse: Vai, e vende o azeite, e paga a teus credores; e tu e teus filhos vivei do que restar."},"fr":{"prompt":"Quand l’huile eut rempli les vases, que dit Élisée à la femme ?","bible_ref":"2 Rois 4:7","verse_text":"Elle alla le rapporter à l’homme de Dieu, et il dit: Va vendre l’huile, et paie ta dette; et tu vivras, toi et tes fils, de ce qui restera."},"en":{"prompt":"When the oil had filled the vessels, what did Elisha tell the woman?","bible_ref":"2 Kings 4:7","verse_text":"Then she came and told the man of God. And he said, Go, sell the oil, and pay thy debt, and live thou and thy children of the rest."},"es":{"prompt":"Cuando el aceite llenó las vasijas, ¿qué dijo Eliseo a la mujer?","bible_ref":"2 Reyes 4:7","verse_text":"Vino ella luego, y contólo al varón de Dios, el cual dijo: Ve, y vende el aceite, y paga á tus acreedores; y tú y tus hijos vivid de lo que quedare."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vende o azeite e paga aos teus credores"},"fr":{"text":"Va vendre l’huile, et paie ta dette"},"en":{"text":"Go, sell the oil, and pay thy debt"},"es":{"text":"Vende el aceite y paga a tus acreedores"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Leva o azeite para o templo"},"fr":{"text":"Porte l’huile au temple"},"en":{"text":"Take the oil to the temple"},"es":{"text":"Lleva el aceite al templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dá o azeite aos sacerdotes"},"fr":{"text":"Donne l’huile aux sacrificateurs"},"en":{"text":"Give the oil to the priests"},"es":{"text":"Da el aceite a los sacerdotes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Derrama o azeite no chão"},"fr":{"text":"Répands l’huile par terre"},"en":{"text":"Pour the oil on the ground"},"es":{"text":"Derrama el aceite en el suelo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-011","type":"choice","level":"easy","testament":"ot","book":"2KI","chapter":6,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Quando o exército sírio desceu contra Eliseu, com que pediu ele a Deus que o ferisse?","bible_ref":"2 Reis 6:18","verse_text":"E logo que os sírios desceram a ele, orou Eliseu ao SENHOR, e disse: Rogo-te que firas a esta gente com cegueira. E feriu-os com cegueira, conforme ao dito de Eliseu."},"fr":{"prompt":"Quand l’armée syrienne descendit vers Élisée, de quoi demanda-t-il à Dieu de la frapper ?","bible_ref":"2 Rois 6:18","verse_text":"Les Syriens descendirent vers Élisée. Il adressa alors cette prière à l’Éternel: Daigne frapper d’aveuglement cette nation! Et l’Éternel les frappa d’aveuglement, selon la parole d’Élisée."},"en":{"prompt":"When the Syrian army came down to Elisha, what did he ask God to smite them with?","bible_ref":"2 Kings 6:18","verse_text":"And when they came down to him, Elisha prayed unto the LORD, and said, Smite this people, I pray thee, with blindness. And he smote them with blindness according to the word of Elisha."},"es":{"prompt":"Cuando el ejército sirio descendió contra Eliseo, ¿con qué pidió a Dios que lo hiriera?","bible_ref":"2 Reyes 6:18","verse_text":"Y luego que los Siros descendieron á él, oró Eliseo á Jehová, y dijo: Ruégote que hieras á esta gente con ceguedad. E hiriólos con ceguedad, conforme al dicho de Eliseo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com cegueira"},"fr":{"text":"D’aveuglement"},"en":{"text":"With blindness"},"es":{"text":"Con ceguedad"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com lepra"},"fr":{"text":"De lèpre"},"en":{"text":"With leprosy"},"es":{"text":"Con lepra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com fogo do céu"},"fr":{"text":"Du feu du ciel"},"en":{"text":"With fire from heaven"},"es":{"text":"Con fuego del cielo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com granizo"},"fr":{"text":"De grêle"},"en":{"text":"With hail"},"es":{"text":"Con granizo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-012","type":"choice","level":"easy","testament":"ot","book":"1CH","chapter":22,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Que nome disse Deus que teria o filho de David que seria «homem de repouso»?","bible_ref":"1 Crónicas 22:9","verse_text":"Eis aqui, um filho te nascerá, o qual será homem de repouso, porque eu lhe darei quietude de todos seus inimigos em derredor; por tanto seu nome será Salomão; e eu darei paz e repouso sobre Israel em seus dias:"},"fr":{"prompt":"Quel nom Dieu dit-il que porterait le fils de David, « homme de repos » ?","bible_ref":"1 Chroniques 22:9","verse_text":"Voici, il te naîtra un fils, qui sera un homme de repos, et à qui je donnerai du repos en le délivrant de tous ses ennemis d’alentour; car Salomon sera son nom, et je ferai venir sur Israël la paix et la tranquillité pendant sa vie."},"en":{"prompt":"What name did God say David’s son, “a man of rest”, would have?","bible_ref":"1 Chronicles 22:9","verse_text":"Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days."},"es":{"prompt":"¿Qué nombre dijo Dios que tendría el hijo de David, «varón de reposo»?","bible_ref":"1 Crónicas 22:9","verse_text":"He aquí, un hijo te nacerá, el cual será varón de reposo, porque yo le daré quietud de todos sus enemigos en derredor; por tanto su nombre será Salomón; y yo daré paz y reposo sobre Israel en sus días:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Salomão"},"fr":{"text":"Salomon"},"en":{"text":"Solomon"},"es":{"text":"Salomón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Absalão"},"fr":{"text":"Absalom"},"en":{"text":"Absalom"},"es":{"text":"Absalom"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Amnom"},"fr":{"text":"Amnon"},"en":{"text":"Amnon"},"es":{"text":"Amnón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Adonias"},"fr":{"text":"Adonija"},"en":{"text":"Adonijah"},"es":{"text":"Adonías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-013","type":"choice","level":"easy","testament":"ot","book":"2CH","chapter":34,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"O que encontrou o sacerdote Hilquias na casa do SENHOR, no tempo do rei Josias?","bible_ref":"2 Crónicas 34:15","verse_text":"E dando conta Hilquias, disse a Safã escriba: Eu ei achado o livro da lei na casa do SENHOR. E deu Hilquias o livro a Safã."},"fr":{"prompt":"Qu’est-ce que le sacrificateur Hilkija trouva dans la maison de l’Éternel, au temps du roi Josias ?","bible_ref":"2 Chroniques 34:15","verse_text":"Alors Hilkija prit la parole et dit à Schaphan, le secrétaire: J’ai trouvé le livre de la loi dans la maison de l’Éternel. Et Hilkija donna le livre à Schaphan."},"en":{"prompt":"What did Hilkiah the priest find in the house of the LORD in the days of king Josiah?","bible_ref":"2 Chronicles 34:15","verse_text":"And Hilkiah answered and said to Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah delivered the book to Shaphan."},"es":{"prompt":"¿Qué halló el sacerdote Hilcías en la casa de Jehová, en tiempos del rey Josías?","bible_ref":"2 Crónicas 34:15","verse_text":"Y dando cuenta Hilcías, dijo á Saphán escriba: Yo he hallado el libro de la ley en la casa de Jehová. Y dió Hilcías el libro á Saphán."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O livro da lei"},"fr":{"text":"Le livre de la loi"},"en":{"text":"The book of the law"},"es":{"text":"El libro de la ley"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um tesouro de ouro"},"fr":{"text":"Un trésor d’or"},"en":{"text":"A treasure of gold"},"es":{"text":"Un tesoro de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A vara de Arão"},"fr":{"text":"La verge d’Aaron"},"en":{"text":"Aaron’s rod"},"es":{"text":"La vara de Aarón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A coroa de David"},"fr":{"text":"La couronne de David"},"en":{"text":"David’s crown"},"es":{"text":"La corona de David"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-014","type":"choice","level":"easy","testament":"ot","book":"EZR","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo o decreto de Ciro, a que cidade devia subir o povo para edificar a casa do SENHOR?","bible_ref":"Esdras 1:3","verse_text":"Quem há entre vós de todo seu povo, seu Deus seja com ele, e suba a Jerusalém que está em Judá, e edifique a casa ao SENHOR Deus de Israel; ele é o Deus que habita em Jerusalém."},"fr":{"prompt":"Selon l’édit de Cyrus, dans quelle ville le peuple devait-il monter pour bâtir la maison de l’Éternel ?","bible_ref":"Esdras 1:3","verse_text":"Qui d’entre vous est de son peuple? Que son Dieu soit avec lui, et qu’il monte à Jérusalem en Juda et bâtisse la maison de l’Éternel, le Dieu d’Israël! C’est le Dieu qui est à Jérusalem."},"en":{"prompt":"According to Cyrus’ decree, to which city should the people go up to build the house of the LORD?","bible_ref":"Ezra 1:3","verse_text":"Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the LORD God of Israel, (he is the God,) which is in Jerusalem."},"es":{"prompt":"Según el decreto de Ciro, ¿a qué ciudad debía subir el pueblo para edificar la casa de Jehová?","bible_ref":"Esdras 1:3","verse_text":"¿Quién hay entre vosotros de todo su pueblo? Sea Dios con él, y suba á Jerusalem que está en Judá, y edifique la casa á Jehová Dios de Israel, (él es el Dios,) la cual está en Jerusalem."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jerusalém"},"fr":{"text":"Jérusalem"},"en":{"text":"Jerusalem"},"es":{"text":"Jerusalem"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Babilónia"},"fr":{"text":"Babylone"},"en":{"text":"Babylon"},"es":{"text":"Babilonia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nínive"},"fr":{"text":"Ninive"},"en":{"text":"Nineveh"},"es":{"text":"Nínive"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Samaria"},"fr":{"text":"Samarie"},"en":{"text":"Samaria"},"es":{"text":"Samaria"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-015","type":"choice","level":"easy","testament":"ot","book":"NEH","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Que notícia recebeu Neemias sobre o muro de Jerusalém?","bible_ref":"Neemias 1:3","verse_text":"E me disseram: Os remanescentes, os que restaram do cativeiro lá na província, estão em grande miséria e desprezo; e o muro de Jerusalém está fendido, e suas portas queimadas a fogo."},"fr":{"prompt":"Quelle nouvelle Néhémie reçut-il sur la muraille de Jérusalem ?","bible_ref":"Néhémie 1:3","verse_text":"Ils me répondirent: Ceux qui sont restés de la captivité sont là dans la province, au comble du malheur et de l’opprobre; les murailles de Jérusalem sont en ruines, et ses portes sont consumées par le feu."},"en":{"prompt":"What news did Nehemiah receive about the wall of Jerusalem?","bible_ref":"Nehemiah 1:3","verse_text":"And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire."},"es":{"prompt":"¿Qué noticia recibió Nehemías sobre el muro de Jerusalem?","bible_ref":"Nehemías 1:3","verse_text":"Y dijéronme: El residuo, los que quedaron de la cautividad allí en la provincia, están en gran mal y afrenta, y el muro de Jerusalem derribado, y sus puertas quemadas á fuego."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Estava derrubado e as portas queimadas"},"fr":{"text":"Elle était en ruines et ses portes brûlées"},"en":{"text":"It was broken down and its gates burned"},"es":{"text":"Estaba derribado y sus puertas quemadas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Estava acabado e muito alto"},"fr":{"text":"Elle était achevée et très haute"},"en":{"text":"It was finished and very high"},"es":{"text":"Estaba acabado y muy alto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tinha sido coberto de ouro"},"fr":{"text":"Elle avait été couverte d’or"},"en":{"text":"It had been covered with gold"},"es":{"text":"Había sido cubierto de oro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Estava cercado por um exército"},"fr":{"text":"Elle était assiégée par une armée"},"en":{"text":"It was surrounded by an army"},"es":{"text":"Estaba rodeado por un ejército"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-016","type":"choice","level":"easy","testament":"ot","book":"NEH","chapter":4,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Enquanto reconstruíam o muro, o que tinham os trabalhadores na outra mão?","bible_ref":"Neemias 4:17","verse_text":"Os que edificavam o muro, e os que traziam as cargas e os que carregavam, com uma mão faziam a obra, e na outra tinham armas."},"fr":{"prompt":"Pendant qu’ils rebâtissaient la muraille, que tenaient les ouvriers de l’autre main ?","bible_ref":"Néhémie 4:17","verse_text":"Ceux qui bâtissaient la muraille, et ceux qui portaient ou chargeaient les fardeaux, travaillaient d’une main et tenaient une arme de l’autre;"},"en":{"prompt":"While they rebuilt the wall, what did the workers hold in the other hand?","bible_ref":"Nehemiah 4:17","verse_text":"They which builded on the wall, and they that bare burdens, with those that laded, every one with one of his hands wrought in the work, and with the other hand held a weapon."},"es":{"prompt":"Mientras reedificaban el muro, ¿qué tenían los obreros en la otra mano?","bible_ref":"Nehemías 4:17","verse_text":"Los que edificaban en el muro, y los que llevaban cargas y los que cargaban, con la una mano trabajaban en la obra, y en la otra tenían la espada."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma arma"},"fr":{"text":"Une arme"},"en":{"text":"A weapon"},"es":{"text":"Una espada"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma lâmpada"},"fr":{"text":"Une lampe"},"en":{"text":"A lamp"},"es":{"text":"Una lámpara"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um pão"},"fr":{"text":"Un pain"},"en":{"text":"A loaf of bread"},"es":{"text":"Un pan"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um livro"},"fr":{"text":"Un livre"},"en":{"text":"A book"},"es":{"text":"Un libro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-017","type":"choice","level":"easy","testament":"ot","book":"EST","chapter":2,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Quem criou Ester como sua filha, porque ela não tinha pai nem mãe?","bible_ref":"Ester 2:7","verse_text":"E ele tinha criado a Hadassa, que é Ester, filha de seu tio, porque não tinha pai nem mãe; e ela tinha bela forma, e era linda de aparência; e como seu pai e sua mãe tinham morrido, Mardoqueu a havia tomado como sua filha."},"fr":{"prompt":"Qui éleva Esther comme sa fille, parce qu’elle n’avait ni père ni mère ?","bible_ref":"Esther 2:7","verse_text":"Il élevait Hadassa, qui est Esther, fille de son oncle; car elle n’avait ni père ni mère. La jeune fille était belle de taille et belle de figure. A la mort de son père et de sa mère, Mardochée l’avait adoptée pour fille."},"en":{"prompt":"Who brought up Esther as his own daughter, because she had neither father nor mother?","bible_ref":"Esther 2:7","verse_text":"And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."},"es":{"prompt":"¿Quién crió a Esther como hija suya, porque no tenía padre ni madre?","bible_ref":"Ester 2:7","verse_text":"Y había criado á Hadassa, que es Esther, hija de su tío, porque no tenía padre ni madre; y era moza de hermosa forma y de buen parecer; y como su padre y su madre murieron, Mardochêo la había tomado por hija suya."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mardoqueu"},"fr":{"text":"Mardochée"},"en":{"text":"Mordecai"},"es":{"text":"Mardochêo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Hamã"},"fr":{"text":"Haman"},"en":{"text":"Haman"},"es":{"text":"Amán"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O rei Assuero"},"fr":{"text":"Le roi Assuérus"},"en":{"text":"King Ahasuerus"},"es":{"text":"El rey Assuero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Hegai"},"fr":{"text":"Hégaï"},"en":{"text":"Hegai"},"es":{"text":"Hegai"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-018","type":"choice","level":"easy","testament":"ot","book":"EST","chapter":4,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Durante quantos dias pediu Ester aos judeus que jejuassem por ela?","bible_ref":"Ester 4:16","verse_text":"Vai, e junta a todos os judeus que se acham em Susã, e jejuai por mim, e não comais nem bebais durante três dias, nem de noite nem de dia; eu e minhas virgens também assim jejuaremos; e assim virei ao rei, ainda que não seja segundo à lei; e se eu perecer, perecerei."},"fr":{"prompt":"Pendant combien de jours Esther demanda-t-elle aux Juifs de jeûner pour elle ?","bible_ref":"Esther 4:16","verse_text":"Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, sans manger ni boire pendant trois jours, ni la nuit ni le jour. Moi aussi, je jeûnerai de même avec mes servantes, puis j’entrerai chez le roi, malgré la loi; et si je dois périr, je périrai."},"en":{"prompt":"For how many days did Esther ask the Jews to fast for her?","bible_ref":"Esther 4:16","verse_text":"Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish."},"es":{"prompt":"¿Durante cuántos días pidió Esther a los Judíos que ayunaran por ella?","bible_ref":"Ester 4:16","verse_text":"Ve, y junta á todos los Judíos que se hallan en Susán, y ayunad por mí, y no comáis ni bebáis en tres días, noche ni día: yo también con mis doncellas ayunaré igualmente, y así entraré al rey, aunque no sea conforme á la ley; y si perezco, que perezca."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três dias"},"fr":{"text":"Trois jours"},"en":{"text":"Three days"},"es":{"text":"Tres días"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sete dias"},"fr":{"text":"Sept jours"},"en":{"text":"Seven days"},"es":{"text":"Siete días"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quarenta dias"},"fr":{"text":"Quarante jours"},"en":{"text":"Forty days"},"es":{"text":"Cuarenta días"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um dia"},"fr":{"text":"Un jour"},"en":{"text":"One day"},"es":{"text":"Un día"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-019","type":"order","level":"easy","testament":"ot","book":"1KI","chapter":1,"verse_start":39,"verse_end":39,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"1 Reis 1:39","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"1 Rois 1:39","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"1 Kings 1:39","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"1 Reyes 1:39","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Salomão é ungido rei","ref":"1 Reis 1:39"},"fr":{"text":"Salomon est oint roi","ref":"1 Rois 1:39"},"en":{"text":"Solomon is anointed king","ref":"1 Kings 1:39"},"es":{"text":"Salomón es ungido rey","ref":"1 Reyes 1:39"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Salomão pede um coração com entendimento","ref":"1 Reis 3:9"},"fr":{"text":"Salomon demande un cœur intelligent","ref":"1 Rois 3:9"},"en":{"text":"Solomon asks for an understanding heart","ref":"1 Kings 3:9"},"es":{"text":"Salomón pide un corazón dócil","ref":"1 Reyes 3:9"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Duas mulheres apresentam-se diante do rei","ref":"1 Reis 3:16"},"fr":{"text":"Deux femmes se présentent devant le roi","ref":"1 Rois 3:16"},"en":{"text":"Two women stand before the king","ref":"1 Kings 3:16"},"es":{"text":"Dos mujeres se presentan ante el rey","ref":"1 Reyes 3:16"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Salomão acaba de edificar a casa","ref":"1 Reis 6:14"},"fr":{"text":"Salomon achève de bâtir la maison","ref":"1 Rois 6:14"},"en":{"text":"Solomon builds the house and finishes it","ref":"1 Kings 6:14"},"es":{"text":"Salomón acaba de labrar la casa","ref":"1 Reyes 6:14"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-easy-020","type":"order","level":"easy","testament":"ot","book":"2KI","chapter":5,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"2 Reis 5:1","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"2 Rois 5:1","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"2 Kings 5:1","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"2 Reyes 5:1","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Naamã, general do rei da Síria, é leproso","ref":"2 Reis 5:1"},"fr":{"text":"Naaman, chef de l’armée syrienne, est lépreux","ref":"2 Rois 5:1"},"en":{"text":"Naaman, the Syrian captain, is a leper","ref":"2 Kings 5:1"},"es":{"text":"Naamán, general del rey de Siria, es leproso","ref":"2 Reyes 5:1"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma menina fala do profeta de Samaria","ref":"2 Reis 5:3"},"fr":{"text":"Une petite fille parle du prophète de Samarie","ref":"2 Rois 5:3"},"en":{"text":"A little maid speaks of the prophet in Samaria","ref":"2 Kings 5:3"},"es":{"text":"Una muchacha habla del profeta de Samaria","ref":"2 Reyes 5:3"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Naamã para à porta da casa de Eliseu","ref":"2 Reis 5:9"},"fr":{"text":"Naaman s’arrête à la porte d’Élisée","ref":"2 Rois 5:9"},"en":{"text":"Naaman stands at the door of Elisha’s house","ref":"2 Kings 5:9"},"es":{"text":"Naamán se para a la puerta de Eliseo","ref":"2 Reyes 5:9"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Naamã vai-se embora irritado","ref":"2 Reis 5:11"},"fr":{"text":"Naaman s’en va irrité","ref":"2 Rois 5:11"},"en":{"text":"Naaman goes away wroth","ref":"2 Kings 5:11"},"es":{"text":"Naamán se va enojado","ref":"2 Reyes 5:11"}}}]}$json$::jsonb);
