select public.upsert_bank_question($json${"id":"hist3-easy-029","type":"verse","level":"easy","testament":"ot","book":"NEH","chapter":2,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Então lhes respondi, dizendo-lhes: O Deus dos céus é quem nos dará sucesso; e nós, servos dele, nos levantaremos e _____; pois vós não tendes parte, nem direito, nem memória em Jerusalém.","bible_ref":"Neemias 2:20","verse_text":"Então lhes respondi, dizendo-lhes: O Deus dos céus é quem nos dará sucesso; e nós, servos dele, nos levantaremos e edificaremos; pois vós não tendes parte, nem direito, nem memória em Jerusalém."},"fr":{"prompt":"Et je leur fis cette réponse: Le Dieu des cieux nous donnera le succès. Nous, ses serviteurs, nous nous lèverons et nous _____; mais vous, vous n’avez ni part, ni droit, ni souvenir dans Jérusalem.","bible_ref":"Néhémie 2:20","verse_text":"Et je leur fis cette réponse: Le Dieu des cieux nous donnera le succès. Nous, ses serviteurs, nous nous lèverons et nous bâtirons; mais vous, vous n’avez ni part, ni droit, ni souvenir dans Jérusalem."},"en":{"prompt":"Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and _____: but ye have no portion, nor right, nor memorial, in Jerusalem.","bible_ref":"Nehemiah 2:20","verse_text":"Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem."},"es":{"prompt":"Y volvíles respuesta, y díjeles: El Dios de los cielos, él nos prosperará, y nosotros sus siervos nos levantaremos y _____: que vosotros no tenéis parte, ni derecho, ni memoria en Jerusalem.","bible_ref":"Nehemías 2:20","verse_text":"Y volvíles respuesta, y díjeles: El Dios de los cielos, él nos prosperará, y nosotros sus siervos nos levantaremos y edificaremos: que vosotros no tenéis parte, ni derecho, ni memoria en Jerusalem."}},"options":[{"position":1,