select public.upsert_bank_question($json${"id":"hist3-medium-002","type":"choice","level":"medium","testament":"ot","book":"1KI","chapter":22,"verse_start":34,"verse_end":34,"texts":{"pt":{"prompt":"Como foi ferido o rei de Israel na batalha?","bible_ref":"1 Reis 22:34","verse_text":"E um homem disparando seu arco ao acaso, feriu ao rei de Israel por entre as junturas da armadura; pelo que disse ele a seu condutor do carro: Toma a volta, e tira-me do campo, que estou ferido."},"fr":{"prompt":"Comment le roi d’Israël fut-il blessé dans la bataille ?","bible_ref":"1 Rois 22:34","verse_text":"Alors un homme tira de son arc au hasard, et frappa le roi d’Israël au défaut de la cuirasse. Le roi dit à celui qui dirigeait son char: Tourne, et fais-moi sortir du champ de bataille, car je suis blessé."},"en":{"prompt":"How was the king of Israel wounded in the battle?","bible_ref":"1 Kings 22:34","verse_text":"And a certain man drew a bow at a venture, and smote the king of Israel between the joints of the harness: wherefore he said unto the driver of his chariot, Turn thine hand, and carry me out of the host; for I am wounded."},"es":{"prompt":"¿Cómo fue herido el rey de Israel en la batalla?","bible_ref":"1 Reyes 22:34","verse_text":"Y un hombre disparando su arco á la ventura, hirió al rey de Israel por entre las junturas de la armadura; por lo que dijo él á su carretero: Toma la vuelta, y sácame del campo, que estoy herido."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Por uma flecha disparada ao acaso"},"fr":{"text":"Par une flèche tirée au hasard"},"en":{"text":"By an arrow drawn at a venture"},"es":{"text":"Por una flecha disparada a la ventura"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Por uma pedra de funda"},"fr":{"text":"Par une pierre de fronde"},"en":{"text":"By a stone from a sling"},"es":{"text":"Por una piedra de honda"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Por um golpe de espada"},"fr":{"text":"Par un coup d’épée"},"en":{"text":"By the stroke of a sword"},"es":{"text":"Por un golpe de espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Caiu do seu carro"},"fr":{"text":"Il tomba de son char"},"en":{"text":"He fell from his chariot"},"es":{"text":"Cayó de su carro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-003","type":"choice","level":"medium","testament":"ot","book":"1KI","chapter":22,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Micaías disse que viu todo o Israel disperso pelos montes, como quê?","bible_ref":"1 Reis 22:17","verse_text":"Então ele disse: Eu vi a todo Israel disperso pelos montes, como ovelhas que não têm pastor: e o SENHOR disse: Estes não têm senhor: volte-se cada um a sua casa em paz."},"fr":{"prompt":"Michée dit qu’il voyait tout Israël dispersé sur les montagnes, comme quoi ?","bible_ref":"1 Rois 22:17","verse_text":"Michée répondit: Je vois tout Israël dispersé sur les montagnes, comme des brebis qui n’ont point de berger; et l’Éternel dit: Ces gens n’ont point de maître, que chacun retourne en paix dans sa maison!"},"en":{"prompt":"Micaiah said he saw all Israel scattered upon the hills, as what?","bible_ref":"1 Kings 22:17","verse_text":"And he said, I saw all Israel scattered upon the hills, as sheep that have not a shepherd: and the LORD said, These have no master: let them return every man to his house in peace."},"es":{"prompt":"Michêas dijo que vio a todo Israel esparcido por los montes, ¿como qué?","bible_ref":"1 Reyes 22:17","verse_text":"Entonces él dijo: Yo ví á todo Israel esparcido por los montes, como ovejas que no tienen pastor: y Jehová dijo: Estos no tienen señor; vuélvase cada uno á su casa en paz."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ovelhas que não têm pastor"},"fr":{"text":"Des brebis qui n’ont point de berger"},"en":{"text":"Sheep that have not a shepherd"},"es":{"text":"Ovejas que no tienen pastor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Folhas levadas pelo vento"},"fr":{"text":"Des feuilles emportées par le vent"},"en":{"text":"Leaves driven by the wind"},"es":{"text":"Hojas llevadas por el viento"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Areia à beira do mar"},"fr":{"text":"Le sable au bord de la mer"},"en":{"text":"The sand on the sea shore"},"es":{"text":"La arena a la orilla del mar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Estrelas do céu"},"fr":{"text":"Les étoiles du ciel"},"en":{"text":"The stars of heaven"},"es":{"text":"Las estrellas del cielo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-004","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":2,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"Depois de Eliseu amaldiçoar os que zombavam dele, quantas ursas saíram do bosque?","bible_ref":"2 Reis 2:24","verse_text":"E olhando ele atrás, viu-os, e amaldiçoou-os no nome do SENHOR. E duas ursas saíram da floresta, e despedaçaram deles quarenta e dois meninos."},"fr":{"prompt":"Après qu’Élisée eut maudit ceux qui se moquaient de lui, combien d’ours sortirent de la forêt ?","bible_ref":"2 Rois 2:24","verse_text":"Il se retourna pour les regarder, et il les maudit au nom de l’Éternel. Alors deux ours sortirent de la forêt, et déchirèrent quarante-deux de ces enfants."},"en":{"prompt":"After Elisha cursed those who mocked him, how many bears came out of the wood?","bible_ref":"2 Kings 2:24","verse_text":"And he turned back, and looked on them, and cursed them in the name of the LORD. And there came forth two she bears out of the wood, and tare forty and two children of them."},"es":{"prompt":"Después de que Eliseo maldijo a los que se burlaban de él, ¿cuántos osos salieron del monte?","bible_ref":"2 Reyes 2:24","verse_text":"Y mirando él atrás, viólos, y maldíjolos en el nombre de Jehová. Y salieron dos osos del monte, y despedazaron de ellos cuarenta y dos muchachos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Duas"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma"},"fr":{"text":"Un"},"en":{"text":"One"},"es":{"text":"Uno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quarenta e duas"},"fr":{"text":"Quarante-deux"},"en":{"text":"Forty-two"},"es":{"text":"Cuarenta y dos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-005","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":2,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"O que pediu Eliseu a Elias, antes de este ser tirado de junto dele?","bible_ref":"2 Reis 2:9","verse_text":"E quando houveram passado, Elias disse a Eliseu: Pede o que queres que faça por ti, antes que seja tirado de contigo. E disse Eliseu: Rogo-te que a porção dobrada de teu espírito seja sobre mim."},"fr":{"prompt":"Que demanda Élisée à Élie, avant qu’il fût enlevé d’avec lui ?","bible_ref":"2 Rois 2:9","verse_text":"Lorsqu’ils eurent passé, Élie dit à Élisée: Demande ce que tu veux que je fasse pour toi, avant que je sois enlevé d’avec toi. Élisée répondit: Qu’il y ait sur moi, je te prie, une double portion de ton esprit!"},"en":{"prompt":"What did Elisha ask of Elijah before he was taken away from him?","bible_ref":"2 Kings 2:9","verse_text":"And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."},"es":{"prompt":"¿Qué pidió Eliseo a Elías antes de que fuera quitado de con él?","bible_ref":"2 Reyes 2:9","verse_text":"Y como hubieron pasado, Elías dijo á Eliseo: Pide lo que quieres que haga por ti, antes que sea quitado de contigo. Y dijo Eliseo: Ruégote que las dos partes de tu espíritu sean sobre mí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A porção dobrada do seu espírito"},"fr":{"text":"Une double portion de son esprit"},"en":{"text":"A double portion of his spirit"},"es":{"text":"Las dos partes de su espíritu"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu manto e o seu cajado"},"fr":{"text":"Son manteau et son bâton"},"en":{"text":"His mantle and his staff"},"es":{"text":"Su manto y su báculo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma vida longa"},"fr":{"text":"Une longue vie"},"en":{"text":"A long life"},"es":{"text":"Una larga vida"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Riquezas e honra"},"fr":{"text":"Des richesses et de la gloire"},"en":{"text":"Riches and honour"},"es":{"text":"Riquezas y honra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-006","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":4,"verse_start":43,"verse_end":43,"texts":{"pt":{"prompt":"Segundo o servo de Eliseu, diante de quantos homens devia pôr aquela pouca comida?","bible_ref":"2 Reis 4:43","verse_text":"E respondeu seu servente: Como porei isto diante de cem homens? Mas ele voltou a dizer: Dá ao povo para que comam, porque assim disse o SENHOR: Comerão, e sobrará."},"fr":{"prompt":"Selon le serviteur d’Élisée, à combien de personnes devait-il donner ce peu de nourriture ?","bible_ref":"2 Rois 4:43","verse_text":"Son serviteur répondit: Comment pourrais-je en donner à cent personnes? Mais Élisée dit: Donne à ces gens, et qu’ils mangent; car ainsi parle l’Éternel: On mangera, et on en aura de reste."},"en":{"prompt":"According to Elisha’s servitor, before how many men should he set that little food?","bible_ref":"2 Kings 4:43","verse_text":"And his servitor said, What, should I set this before an hundred men? He said again, Give the people, that they may eat: for thus saith the LORD, They shall eat, and shall leave thereof."},"es":{"prompt":"Según el sirviente de Eliseo, ¿delante de cuántos hombres debía poner aquella poca comida?","bible_ref":"2 Reyes 4:43","verse_text":"Y respondió su sirviente: ¿Cómo he de poner esto delante de cien hombres? Mas él tornó á decir: Da á la gente para que coman, porque así ha dicho Jehová: Comerán, y sobrará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cem"},"fr":{"text":"Cent"},"en":{"text":"An hundred"},"es":{"text":"Cien"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cinquenta"},"fr":{"text":"Cinquante"},"en":{"text":"Fifty"},"es":{"text":"Cincuenta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mil"},"fr":{"text":"Mille"},"en":{"text":"A thousand"},"es":{"text":"Mil"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-007","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":13,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"O que aconteceu ao homem morto que tocou nos ossos de Eliseu?","bible_ref":"2 Reis 13:21","verse_text":"E aconteceu que ao sepultar uns um homem, subitamente viram uma tropa, e lançaram ao homem no sepulcro de Eliseu: e quando o morto chegou a tocar os ossos de Eliseu, reviveu, e levantou-se sobre seus pés."},"fr":{"prompt":"Qu’arriva-t-il à l’homme mort qui toucha les os d’Élisée ?","bible_ref":"2 Rois 13:21","verse_text":"Et comme on enterrait un homme, voici, on aperçut une de ces troupes, et l’on jeta l’homme dans le sépulcre d’Élisée. L’homme alla toucher les os d’Élisée, et il reprit vie et se leva sur ses pieds."},"en":{"prompt":"What happened to the dead man who touched the bones of Elisha?","bible_ref":"2 Kings 13:21","verse_text":"And it came to pass, as they were burying a man, that, behold, they spied a band of men; and they cast the man into the sepulchre of Elisha: and when the man was let down, and touched the bones of Elisha, he revived, and stood up on his feet."},"es":{"prompt":"¿Qué le pasó al hombre muerto que tocó los huesos de Eliseo?","bible_ref":"2 Reyes 13:21","verse_text":"Y aconteció que al sepultar unos un hombre, súbitamente vieron una partida, y arrojaron al hombre en el sepulcro de Eliseo: y cuando llegó á tocar el muerto los huesos de Eliseo, revivió, y levantóse sobre sus pies."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Reviveu e pôs-se de pé"},"fr":{"text":"Il reprit vie et se leva sur ses pieds"},"en":{"text":"He revived and stood up on his feet"},"es":{"text":"Revivió y se levantó sobre sus pies"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ficou leproso"},"fr":{"text":"Il devint lépreux"},"en":{"text":"He became a leper"},"es":{"text":"Quedó leproso"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Transformou-se em pó"},"fr":{"text":"Il devint poussière"},"en":{"text":"He turned to dust"},"es":{"text":"Se convirtió en polvo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Foi levado num redemoinho"},"fr":{"text":"Il fut enlevé dans un tourbillon"},"en":{"text":"He was taken up in a whirlwind"},"es":{"text":"Fue llevado en un torbellino"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-008","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":5,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Que criado de Eliseu decidiu correr atrás de Naamã para lhe tirar alguma coisa?","bible_ref":"2 Reis 5:20","verse_text":"Então Geazi, criado de Eliseu o homem de Deus, disse entre si: Eis que meu senhor poupou a este sírio Naamã, não tomando de sua mão as coisas que havia trazido. Vive o SENHOR, que correrei eu atrás dele, e tomarei dele alguma coisa."},"fr":{"prompt":"Quel serviteur d’Élisée décida de courir après Naaman pour en obtenir quelque chose ?","bible_ref":"2 Rois 5:20","verse_text":"Guéhazi, serviteur d’Élisée, homme de Dieu, se dit en lui-même: Voici, mon maître a ménagé Naaman, ce Syrien, en n’acceptant pas de sa main ce qu’il avait apporté; l’Éternel est vivant! Je vais courir après lui, et j’en obtiendrai quelque chose."},"en":{"prompt":"Which servant of Elisha decided to run after Naaman and take somewhat of him?","bible_ref":"2 Kings 5:20","verse_text":"But Gehazi, the servant of Elisha the man of God, said, Behold, my master hath spared Naaman this Syrian, in not receiving at his hands that which he brought: but, as the LORD liveth, I will run after him, and take somewhat of him."},"es":{"prompt":"¿Qué criado de Eliseo decidió correr tras Naamán para tomar de él alguna cosa?","bible_ref":"2 Reyes 5:20","verse_text":"Entonces Giezi, criado de Eliseo el varón de Dios, dijo entre sí: He aquí mi señor estorbó á este Siro Naamán, no tomando de su mano las cosas que había traído. Vive Jehová, que correré yo tras él, y tomaré de él alguna cosa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Geazi"},"fr":{"text":"Guéhazi"},"en":{"text":"Gehazi"},"es":{"text":"Giezi"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Obadias"},"fr":{"text":"Abdias"},"en":{"text":"Obadiah"},"es":{"text":"Abdías"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jeú"},"fr":{"text":"Jéhu"},"en":{"text":"Jehu"},"es":{"text":"Jehú"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Joabe"},"fr":{"text":"Joab"},"en":{"text":"Joab"},"es":{"text":"Joab"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-009","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":23,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Que festa mandou o rei Josias celebrar, conforme o livro da aliança?","bible_ref":"2 Reis 23:21","verse_text":"Então mandou o rei a todo o povo, dizendo: Fazei a páscoa ao SENHOR vosso Deus, conforme o que está escrito no livro desta aliança."},"fr":{"prompt":"Quelle fête le roi Josias ordonna-t-il de célébrer, selon le livre de l’alliance ?","bible_ref":"2 Rois 23:21","verse_text":"Le roi donna cet ordre à tout le peuple: Célébrez la Pâque en l’honneur de l’Éternel, votre Dieu, comme il est écrit dans ce livre de l’alliance."},"en":{"prompt":"Which feast did king Josiah command to keep, as written in the book of the covenant?","bible_ref":"2 Kings 23:21","verse_text":"And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant."},"es":{"prompt":"¿Qué fiesta mandó celebrar el rey Josías, conforme al libro de la alianza?","bible_ref":"2 Reyes 23:21","verse_text":"Entonces mandó el rey á todo el pueblo, diciendo: Haced la pascua á Jehová vuestro Dios, conforme á lo que está escrito en el libro de esta alianza."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A Páscoa"},"fr":{"text":"La Pâque"},"en":{"text":"The passover"},"es":{"text":"La pascua"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A festa das trombetas"},"fr":{"text":"La fête des trompettes"},"en":{"text":"The feast of trumpets"},"es":{"text":"La fiesta de las trompetas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A festa da colheita"},"fr":{"text":"La fête de la moisson"},"en":{"text":"The feast of harvest"},"es":{"text":"La fiesta de la siega"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A dedicação do muro"},"fr":{"text":"La dédicace des murailles"},"en":{"text":"The dedication of the wall"},"es":{"text":"La dedicación del muro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-010","type":"choice","level":"medium","testament":"ot","book":"1CH","chapter":17,"verse_start":3,"verse_end":4,"texts":{"pt":{"prompt":"A que profeta mandou Deus dizer a David: «Tu não me edificarás casa»?","bible_ref":"1 Crónicas 17:3-4","verse_text":"Naquela mesma noite foi palavra de Deus a Natã, dizendo: Vai e dize a Davi meu servo: Assim disse o SENHOR: Tu não me edificarás casa em que habite:"},"fr":{"prompt":"À quel prophète Dieu dit-il d’annoncer à David : « Ce ne sera pas toi qui me bâtiras une maison » ?","bible_ref":"1 Chroniques 17:3-4","verse_text":"La nuit suivante, la parole de Dieu fut adressée à Nathan: Va dire à mon serviteur David: Ainsi parle l’Éternel: Ce ne sera pas toi qui me bâtiras une maison pour que j’en fasse ma demeure."},"en":{"prompt":"Which prophet was sent to tell David, “Thou shalt not build me an house”?","bible_ref":"1 Chronicles 17:3-4","verse_text":"And it came to pass the same night, that the word of God came to Nathan, saying, Go and tell David my servant, Thus saith the LORD, Thou shalt not build me an house to dwell in:"},"es":{"prompt":"¿A qué profeta mandó Dios decir a David: «Tú no me edificarás casa»?","bible_ref":"1 Crónicas 17:3-4","verse_text":"En aquella misma noche fué palabra de Dios á Nathán, diciendo: Ve y di á David mi siervo: Así ha dicho Jehová: Tú no me edificarás casa en que habite:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Natã"},"fr":{"text":"Nathan"},"en":{"text":"Nathan"},"es":{"text":"Nathán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gade"},"fr":{"text":"Gad"},"en":{"text":"Gad"},"es":{"text":"Gad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elijah"},"es":{"text":"Elías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-011","type":"choice","level":"medium","testament":"ot","book":"1CH","chapter":15,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo David, quem devia levar a arca de Deus?","bible_ref":"1 Crónicas 15:2","verse_text":"Então Davi disse: Ninguém pode trazer a arca de Deus, a não ser os levitas; porque o SENHOR os escolheu para que transportassem a arca do SENHOR, e para lhe servirem eternamente."},"fr":{"prompt":"Selon David, par qui l’arche de Dieu devait-elle être portée ?","bible_ref":"1 Chroniques 15:2","verse_text":"Alors David dit: L’arche de Dieu ne doit être portée que par les Lévites, car l’Éternel les a choisis pour porter l’arche de Dieu et pour en faire le service à toujours."},"en":{"prompt":"According to David, who ought to carry the ark of God?","bible_ref":"1 Chronicles 15:2","verse_text":"Then David said, None ought to carry the ark of God but the Levites: for them hath the LORD chosen to carry the ark of God, and to minister unto him for ever."},"es":{"prompt":"Según David, ¿quién debía llevar el arca de Dios?","bible_ref":"1 Crónicas 15:2","verse_text":"Entonces dijo David: El arca de Dios no debe ser traída sino por los Levitas; porque á ellos ha elegido Jehová para que lleven el arca de Jehová, y le sirvan perpetuamente."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Só os levitas"},"fr":{"text":"Seulement les Lévites"},"en":{"text":"Only the Levites"},"es":{"text":"Solo los Levitas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os valentes de David"},"fr":{"text":"Les vaillants hommes de David"},"en":{"text":"David’s mighty men"},"es":{"text":"Los valientes de David"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Bois num carro novo"},"fr":{"text":"Des bœufs sur un char neuf"},"en":{"text":"Oxen on a new cart"},"es":{"text":"Bueyes en un carro nuevo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os anciãos de Israel"},"fr":{"text":"Les anciens d’Israël"},"en":{"text":"The elders of Israel"},"es":{"text":"Los ancianos de Israel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-012","type":"choice","level":"medium","testament":"ot","book":"2CH","chapter":26,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Que rei ficou leproso quando, irado, queria queimar incenso na casa do SENHOR?","bible_ref":"2 Crónicas 26:19","verse_text":"E irou-se Uzias, que tinha o incenso na mão para queimá-lo; e em esta sua ira contra os sacerdotes, a lepra lhe surgiu na testa diante dos sacerdotes na casa do SENHOR, junto ao altar do incenso."},"fr":{"prompt":"Quel roi devint lépreux quand, irrité, il voulait brûler des parfums dans la maison de l’Éternel ?","bible_ref":"2 Chroniques 26:19","verse_text":"La colère s’empara d’Ozias, qui tenait un encensoir à la main. Et comme il s’irritait contre les sacrificateurs, la lèpre éclata sur son front, en présence des sacrificateurs, dans la maison de l’Éternel, près de l’autel des parfums."},"en":{"prompt":"Which king became a leper when, in his wrath, he would burn incense in the house of the LORD?","bible_ref":"2 Chronicles 26:19","verse_text":"Then Uzziah was wroth, and had a censer in his hand to burn incense: and while he was wroth with the priests, the leprosy even rose up in his forehead before the priests in the house of the LORD, from beside the incense altar."},"es":{"prompt":"¿Qué rey quedó leproso cuando, airado, quería quemar perfume en la casa de Jehová?","bible_ref":"2 Crónicas 26:19","verse_text":"Y airóse Uzzías, que tenía el perfume en la mano para quemarlo; y en esta su ira contra los sacerdotes, la lepra le salió en la frente delante de los sacerdotes en la casa de Jehová, junto al altar del perfume."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uzias"},"fr":{"text":"Ozias"},"en":{"text":"Uzziah"},"es":{"text":"Uzzías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ezequias"},"fr":{"text":"Ézéchias"},"en":{"text":"Hezekiah"},"es":{"text":"Ezechîas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josias"},"fr":{"text":"Josias"},"en":{"text":"Josiah"},"es":{"text":"Josías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josafá"},"fr":{"text":"Josaphat"},"en":{"text":"Jehoshaphat"},"es":{"text":"Josaphat"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-013","type":"choice","level":"medium","testament":"ot","book":"2CH","chapter":15,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo o profeta que foi ao encontro de Asa, quando estaria o SENHOR com o povo?","bible_ref":"2 Crónicas 15:2","verse_text":"E saiu ao encontro a Asa, e disse-lhe: Ouvi-me, Asa, e todo Judá e Benjamim: o SENHOR é convosco, se vós fordes com ele: e se lhe buscardes, será achado de vós; mas se lhe deixardes, ele também vos deixará."},"fr":{"prompt":"Selon le prophète venu au-devant d’Asa, quand l’Éternel serait-il avec le peuple ?","bible_ref":"2 Chroniques 15:2","verse_text":"et Azaria alla au-devant d’Asa et lui dit: Écoutez-moi, Asa, et tout Juda et Benjamin! L’Éternel est avec vous quand vous êtes avec lui; si vous le cherchez, vous le trouverez; mais si vous l’abandonnez, il vous abandonnera."},"en":{"prompt":"According to the prophet who went out to meet Asa, when would the LORD be with the people?","bible_ref":"2 Chronicles 15:2","verse_text":"And he went out to meet Asa, and said unto him, Hear ye me, Asa, and all Judah and Benjamin; The LORD is with you, while ye be with him; and if ye seek him, he will be found of you; but if ye forsake him, he will forsake you."},"es":{"prompt":"Según el profeta que salió al encuentro de Asa, ¿cuándo estaría Jehová con el pueblo?","bible_ref":"2 Crónicas 15:2","verse_text":"Y salió al encuentro á Asa, y díjole: Oidme, Asa, y todo Judá y Benjamín: Jehová es con vosotros, si vosotros fuereis con él: y si le buscareis, será hallado de vosotros; mas si le dejareis, él también os dejará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Enquanto eles estivessem com Ele"},"fr":{"text":"Quand ils seraient avec lui"},"en":{"text":"While they were with him"},"es":{"text":"Mientras ellos estuvieran con él"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Enquanto tivessem um rei"},"fr":{"text":"Tant qu’ils auraient un roi"},"en":{"text":"While they had a king"},"es":{"text":"Mientras tuvieran rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Enquanto o templo estivesse de pé"},"fr":{"text":"Tant que le temple serait debout"},"en":{"text":"While the temple stood"},"es":{"text":"Mientras el templo estuviera en pie"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sempre, fizessem o que fizessem"},"fr":{"text":"Toujours, quoi qu’ils fassent"},"en":{"text":"Always, whatever they did"},"es":{"text":"Siempre, hicieran lo que hicieran"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-014","type":"choice","level":"medium","testament":"ot","book":"EZR","chapter":1,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Quem tinha levado de Jerusalém os utensílios da casa do SENHOR que Ciro devolveu?","bible_ref":"Esdras 1:7","verse_text":"Também o rei Ciro tirou os utensílios da casa do SENHOR, que Nabucodonosor tinha trazido de Jerusalém, e posto na casa de seus deuses."},"fr":{"prompt":"Qui avait emporté de Jérusalem les ustensiles de la maison de l’Éternel que Cyrus rendit ?","bible_ref":"Esdras 1:7","verse_text":"Le roi Cyrus rendit les ustensiles de la maison de l’Éternel, que Nebucadnetsar avait emportés de Jérusalem et placés dans la maison de son dieu."},"en":{"prompt":"Who had carried out of Jerusalem the vessels of the house of the LORD that Cyrus brought forth?","bible_ref":"Ezra 1:7","verse_text":"Also Cyrus the king brought forth the vessels of the house of the LORD, which Nebuchadnezzar had brought forth out of Jerusalem, and had put them in the house of his gods;"},"es":{"prompt":"¿Quién había sacado de Jerusalem los vasos de la casa de Jehová que Ciro devolvió?","bible_ref":"Esdras 1:7","verse_text":"Y el rey Ciro sacó los vasos de la casa de Jehová, que Nabucodonosor había traspasado de Jerusalem, y puesto en la casa de sus dioses."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nabucodonosor"},"fr":{"text":"Nebucadnetsar"},"en":{"text":"Nebuchadnezzar"},"es":{"text":"Nabucodonosor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Senaqueribe"},"fr":{"text":"Sanchérib"},"en":{"text":"Sennacherib"},"es":{"text":"Sennachêrib"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Faraó"},"fr":{"text":"Pharaon"},"en":{"text":"Pharaoh"},"es":{"text":"Faraón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dario"},"fr":{"text":"Darius"},"en":{"text":"Darius"},"es":{"text":"Darío"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-015","type":"choice","level":"medium","testament":"ot","book":"EZR","chapter":4,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quando os adversários quiseram edificar com eles, o que responderam Zorobabel e Jesua?","bible_ref":"Esdras 4:3","verse_text":"Porém Zorobabel, Jesua, e os demais chefes das famílias de Israel lhes disseram: Não nos convém edificar convosco casa a nosso Deus; mas somente nós a edificaremos ao SENHOR, Deus de Israel, como nos mandou o rei Ciro, rei da Pérsia."},"fr":{"prompt":"Quand les ennemis voulurent bâtir avec eux, que répondirent Zorobabel et Josué ?","bible_ref":"Esdras 4:3","verse_text":"Mais Zorobabel, Josué, et les autres chefs des familles d’Israël, leur répondirent: Ce n’est pas à vous et à nous de bâtir la maison de notre Dieu; nous la bâtirons nous seuls à l’Éternel, le Dieu d’Israël, comme nous l’a ordonné le roi Cyrus, roi de Perse."},"en":{"prompt":"When the adversaries wanted to build with them, what did Zerubbabel and Jeshua answer?","bible_ref":"Ezra 4:3","verse_text":"But Zerubbabel, and Jeshua, and the rest of the chief of the fathers of Israel, said unto them, Ye have nothing to do with us to build an house unto our God; but we ourselves together will build unto the LORD God of Israel, as king Cyrus the king of Persia hath commanded us."},"es":{"prompt":"Cuando los enemigos quisieron edificar con ellos, ¿qué respondieron Zorobabel y Jesuá?","bible_ref":"Esdras 4:3","verse_text":"Y díjoles Zorobabel, y Jesuá, y los demás cabezas de los padres de Israel: No nos conviene edificar con vosotros casa á nuestro Dios, sino que nosotros solos la edificaremos á Jehová Dios de Israel, como nos mandó el rey Ciro, rey de Persia."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Que só eles edificariam a casa"},"fr":{"text":"Qu’ils bâtiraient la maison eux seuls"},"en":{"text":"That they alone would build the house"},"es":{"text":"Que ellos solos edificarían la casa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Que aceitavam a sua ajuda"},"fr":{"text":"Qu’ils acceptaient leur aide"},"en":{"text":"That they welcomed their help"},"es":{"text":"Que aceptaban su ayuda"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Que primeiro tinham de pagar ouro"},"fr":{"text":"Qu’ils devaient d’abord payer de l’or"},"en":{"text":"That they must first pay gold"},"es":{"text":"Que primero debían pagar oro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Que esperariam pelo profeta"},"fr":{"text":"Qu’ils attendraient le prophète"},"en":{"text":"That they would wait for the prophet"},"es":{"text":"Que esperarían al profeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-016","type":"choice","level":"medium","testament":"ot","book":"EZR","chapter":7,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Esdras 7:6, o que era Esdras?","bible_ref":"Esdras 7:6","verse_text":"este Esdras subiu da Babilônia; e ele era escriba habilidoso na lei de Moisés, dada pelo SENHOR Deus de Israel; e segundo a mão do SENHOR, seu Deus, sobre ele, o rei lhe deu tudo quanto lhe pedira."},"fr":{"prompt":"Selon Esdras 7:6, qu’était Esdras ?","bible_ref":"Esdras 7:6","verse_text":"Cet Esdras vint de Babylone: c’était un scribe versé dans la loi de Moïse, donnée par l’Éternel, le Dieu d’Israël. Et comme la main de l’Éternel, son Dieu, était sur lui, le roi lui accorda tout ce qu’il avait demandé."},"en":{"prompt":"According to Ezra 7:6, what was Ezra?","bible_ref":"Ezra 7:6","verse_text":"This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."},"es":{"prompt":"Según Esdras 7:6, ¿qué era Esdras?","bible_ref":"Esdras 7:6","verse_text":"Este Esdras subió de Babilonia, el cual era escriba diligente en la ley de Moisés, que Jehová Dios de Israel había dado; y concedióle el rey, según la mano de Jehová su Dios sobre él, todo lo que pidió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Escriba hábil na lei de Moisés"},"fr":{"text":"Un scribe versé dans la loi de Moïse"},"en":{"text":"A ready scribe in the law of Moses"},"es":{"text":"Escriba diligente en la ley de Moisés"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Copeiro do rei"},"fr":{"text":"Échanson du roi"},"en":{"text":"The king’s cupbearer"},"es":{"text":"Copero del rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Governador de Judá"},"fr":{"text":"Gouverneur de Juda"},"en":{"text":"Governor of Judah"},"es":{"text":"Gobernador de Judá"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Guarda do bosque do rei"},"fr":{"text":"Garde forestier du roi"},"en":{"text":"Keeper of the king’s forest"},"es":{"text":"Guarda del bosque del rey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-017","type":"choice","level":"medium","testament":"ot","book":"NEH","chapter":8,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Neemias 8:8, como era lido o livro da lei ao povo?","bible_ref":"Neemias 8:8","verse_text":"E leram no livro da lei de Deus o declarando, e explicando o sentido, para que pudessem entender o que era lido."},"fr":{"prompt":"Selon Néhémie 8:8, comment lisait-on le livre de la loi au peuple ?","bible_ref":"Néhémie 8:8","verse_text":"Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu."},"en":{"prompt":"According to Nehemiah 8:8, how was the book of the law read to the people?","bible_ref":"Nehemiah 8:8","verse_text":"So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading."},"es":{"prompt":"Según Nehemías 8:8, ¿cómo se leía el libro de la ley al pueblo?","bible_ref":"Nehemías 8:8","verse_text":"Y leían en el libro de la ley de Dios claramente, y ponían el sentido, de modo que entendiesen la lectura."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Explicando o sentido, para que entendessem"},"fr":{"text":"En donnant le sens, pour faire comprendre"},"en":{"text":"Distinctly, giving the sense, so they understood"},"es":{"text":"Poniendo el sentido, para que entendiesen"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em voz baixa, em segredo"},"fr":{"text":"À voix basse, en secret"},"en":{"text":"Quietly, in secret"},"es":{"text":"En voz baja, en secreto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Só diante dos sacerdotes"},"fr":{"text":"Seulement devant les sacrificateurs"},"en":{"text":"Only before the priests"},"es":{"text":"Solo delante de los sacerdotes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cantando ao som de harpas"},"fr":{"text":"En chantant au son des harpes"},"en":{"text":"Singing with harps"},"es":{"text":"Cantando al son de arpas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-018","type":"choice","level":"medium","testament":"ot","book":"NEH","chapter":13,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Para que não entrassem cargas em Jerusalém no sábado, o que mandou Neemias fazer?","bible_ref":"Neemias 13:19","verse_text":"Sucedeu pois, que quando ia escurecendo às portas de Jerusalém antes do sábado, disse que eu mandei que se fechassem as portas, e mandei que não as abrissem até depois do sábado; e pus às portas alguns de meus servos, para que carga nenhuma entrasse no dia de sábado."},"fr":{"prompt":"Pour empêcher l’entrée des fardeaux à Jérusalem le jour du sabbat, qu’ordonna Néhémie ?","bible_ref":"Néhémie 13:19","verse_text":"Puis j’ordonnai qu’on fermât les portes de Jérusalem avant le sabbat, dès qu’elles seraient dans l’ombre, et qu’on ne les ouvrît qu’après le sabbat. Et je plaçai quelques-uns de mes serviteurs aux portes, pour empêcher l’entrée des fardeaux le jour du sabbat."},"en":{"prompt":"So that no burden would be brought into Jerusalem on the sabbath, what did Nehemiah command?","bible_ref":"Nehemiah 13:19","verse_text":"And it came to pass, that when the gates of Jerusalem began to be dark before the sabbath, I commanded that the gates should be shut, and charged that they should not be opened till after the sabbath: and some of my servants set I at the gates, that there should no burden be brought in on the sabbath day."},"es":{"prompt":"Para que no entrase carga en Jerusalem en sábado, ¿qué mandó Nehemías?","bible_ref":"Nehemías 13:19","verse_text":"Sucedió pues, que cuando iba oscureciendo á las puertas de Jerusalem antes del sábado, dije que se cerrasen las puertas, y ordené que no las abriesen hasta después del sábado; y puse á las puertas algunos de mis criados, para que en día de sábado no entrasen carga."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Fechar as portas"},"fr":{"text":"Fermer les portes"},"en":{"text":"To shut the gates"},"es":{"text":"Cerrar las puertas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Derrubar o mercado"},"fr":{"text":"Détruire le marché"},"en":{"text":"To pull down the market"},"es":{"text":"Derribar el mercado"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Queimar as cargas"},"fr":{"text":"Brûler les fardeaux"},"en":{"text":"To burn the burdens"},"es":{"text":"Quemar las cargas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tocar a trombeta"},"fr":{"text":"Sonner de la trompette"},"en":{"text":"To blow the trumpet"},"es":{"text":"Tocar la trompeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-019","type":"choice","level":"medium","testament":"ot","book":"NEH","chapter":4,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Tobias, que animal bastaria para derrubar o muro de pedra?","bible_ref":"Neemias 4:3","verse_text":"E com ele estava Tobias, o amonita, que disse: Ainda que edifiquem, contudo, se uma raposa vier, ela sozinha será capaz de derrubar seu muro de pedra."},"fr":{"prompt":"Selon Tobija, quel animal suffirait à renverser la muraille de pierres ?","bible_ref":"Néhémie 4:3","verse_text":"Tobija, l’Ammonite, était à côté de lui, et il dit: Qu’ils bâtissent seulement! Si un renard s’élance, il renversera leur muraille de pierres!"},"en":{"prompt":"According to Tobiah, which animal would break down the stone wall?","bible_ref":"Nehemiah 4:3","verse_text":"Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall."},"es":{"prompt":"Según Tobías, ¿qué animal bastaría para derribar el muro de piedra?","bible_ref":"Nehemías 4:3","verse_text":"Y estaba junto á él Tobías Ammonita, el cual dijo: Aun lo que ellos edifican, si subiere una zorra derribará su muro de piedra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma raposa"},"fr":{"text":"Un renard"},"en":{"text":"A fox"},"es":{"text":"Una zorra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um leão"},"fr":{"text":"Un lion"},"en":{"text":"A lion"},"es":{"text":"Un león"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um burro"},"fr":{"text":"Un âne"},"en":{"text":"An ass"},"es":{"text":"Un asno"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um rato"},"fr":{"text":"Une souris"},"en":{"text":"A mouse"},"es":{"text":"Un ratón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-020","type":"choice","level":"medium","testament":"ot","book":"EST","chapter":2,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Qual era o outro nome de Ester?","bible_ref":"Ester 2:7","verse_text":"E ele tinha criado a Hadassa, que é Ester, filha de seu tio, porque não tinha pai nem mãe; e ela tinha bela forma, e era linda de aparência; e como seu pai e sua mãe tinham morrido, Mardoqueu a havia tomado como sua filha."},"fr":{"prompt":"Quel était l’autre nom d’Esther ?","bible_ref":"Esther 2:7","verse_text":"Il élevait Hadassa, qui est Esther, fille de son oncle; car elle n’avait ni père ni mère. La jeune fille était belle de taille et belle de figure. A la mort de son père et de sa mère, Mardochée l’avait adoptée pour fille."},"en":{"prompt":"What was Esther’s other name?","bible_ref":"Esther 2:7","verse_text":"And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."},"es":{"prompt":"¿Cuál era el otro nombre de Esther?","bible_ref":"Ester 2:7","verse_text":"Y había criado á Hadassa, que es Esther, hija de su tío, porque no tenía padre ni madre; y era moza de hermosa forma y de buen parecer; y como su padre y su madre murieron, Mardochêo la había tomado por hija suya."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Hadassa"},"fr":{"text":"Hadassa"},"en":{"text":"Hadassah"},"es":{"text":"Hadassa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vasti"},"fr":{"text":"Vasthi"},"en":{"text":"Vashti"},"es":{"text":"Vasthi"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Zeres"},"fr":{"text":"Zéresch"},"en":{"text":"Zeresh"},"es":{"text":"Zeres"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mical"},"fr":{"text":"Mical"},"en":{"text":"Michal"},"es":{"text":"Michâl"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-021","type":"choice","level":"medium","testament":"ot","book":"EST","chapter":6,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quando o rei perguntou que honra se tinha feito a Mardoqueu, o que responderam os servos?","bible_ref":"Ester 6:3","verse_text":"Então o rei disse: Que honra e que condecoração se fez a Mardoqueu por isto? E os servos do rei que o serviam disseram: Nada foi feito com ele."},"fr":{"prompt":"Quand le roi demanda quelle distinction Mardochée avait reçue, que répondirent les serviteurs ?","bible_ref":"Esther 6:3","verse_text":"Le roi dit: Quelle marque de distinction et d’honneur Mardochée a-t-il reçue pour cela? Il n’a rien reçu, répondirent ceux qui servaient le roi."},"en":{"prompt":"When the king asked what honour had been done to Mordecai, what did his servants answer?","bible_ref":"Esther 6:3","verse_text":"And the king said, What honour and dignity hath been done to Mordecai for this? Then said the king’s servants that ministered unto him, There is nothing done for him."},"es":{"prompt":"Cuando el rey preguntó qué honra se había hecho a Mardochêo, ¿qué respondieron los servidores?","bible_ref":"Ester 6:3","verse_text":"Y dijo el rey: ¿Qué honra ó que distinción se hizo á Mardochêo por esto? Y respondieron los servidores del rey, sus oficiales: Nada se ha hecho con él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nada se tinha feito"},"fr":{"text":"Il n’avait rien reçu"},"en":{"text":"Nothing had been done for him"},"es":{"text":"Nada se había hecho"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Tinha recebido uma coroa"},"fr":{"text":"Il avait reçu une couronne"},"en":{"text":"He had received a crown"},"es":{"text":"Había recibido una corona"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tinha sido feito governador"},"fr":{"text":"Il avait été fait gouverneur"},"en":{"text":"He had been made governor"},"es":{"text":"Había sido hecho gobernador"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tinha recebido muito ouro"},"fr":{"text":"Il avait reçu beaucoup d’or"},"en":{"text":"He had received much gold"},"es":{"text":"Había recibido mucho oro"}}}]}$json$::jsonb);
