select public.upsert_bank_question($json${"id":"hist3-medium-031","type":"verse","level":"medium","testament":"ot","book":"1CH","chapter":29,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Tua é, ó o SENHOR, a magnificência, e o poder, e a _____, a vitória, e a honra; porque todas as coisas que estão nos céus e na terra são tuas. Teu, ó o SENHOR, é o reino, e a altura sobre todos os que estão por cabeça.","bible_ref":"1 Crónicas 29:11","verse_text":"Tua é, ó o SENHOR, a magnificência, e o poder, e a glória, a vitória, e a honra; porque todas as coisas que estão nos céus e na terra são tuas. Teu, ó o SENHOR, é o reino, e a altura sobre todos os que estão por cabeça."},"fr":{"prompt":"A toi, Éternel, la grandeur, la force et la magnificence, l’éternité et la _____, car tout ce qui est au ciel et sur la terre t’appartient; à toi, Éternel, le règne, car tu t’élèves souverainement au-dessus de tout!","bible_ref":"1 Chroniques 29:11","verse_text":"A toi, Éternel, la grandeur, la force et la magnificence, l’éternité et la gloire, car tout ce qui est au ciel et sur la terre t’appartient; à toi, Éternel, le règne, car tu t’élèves souverainement au-dessus de tout!"},"en":{"prompt":"Thine, O LORD, is the greatness, and the power, and the _____, and the victory, and the majesty: for all that is in the heaven and in the earth is thine; thine is the kingdom, O LORD, and thou art exalted as head above all.","bible_ref":"1 Chronicles 29:11","verse_text":"Thine, O LORD, is the greatness, and the power, and the glory, and the victory, and the majesty: for all that is in the heaven and in the earth is thine; thine is the kingdom, O LORD, and thou art exalted as head above all."},"es":{"prompt":"Tuya es, oh Jehová, la magnificencia, y el poder, y la _____, la victoria, y el honor; porque todas las cosas que están en los cielos y en la tierra son tuyas. Tuyo, oh Jehová, es el reino, y la altura sobre todos los que están por cabeza.","bible_ref":"1 Crónicas 29:11","verse_text":"Tuya es, oh Jehová, la magnificencia, y el poder, y la gloria, la victoria, y el honor; porque todas las cosas que están en los cielos y en la tierra son tuyas. Tuyo, oh Jehová, es el reino, y la altura sobre todos los que están por cabeza."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"justiça"},"fr":{"text":"justice"},"en":{"text":"justice"},"es":{"text":"justicia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"sabedoria"},"fr":{"text":"sagesse"},"en":{"text":"wisdom"},"es":{"text":"sabiduría"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"glória"},"fr":{"text":"gloire"},"en":{"text":"glory"},"es":{"text":"gloria"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"riqueza"},"fr":{"text":"richesse"},"en":{"text":"riches"},"es":{"text":"riqueza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-032","type":"verse","level":"medium","testament":"ot","book":"2CH","chapter":20,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"E disse: Ouvi, Judá todo, e vós moradores de Jerusalém, e tu, rei Josafá. o SENHOR vos diz assim: Não temais nem vos amedronteis diante desta tão grande _____; porque não é vossa a guerra, mas sim de Deus.","bible_ref":"2 Crónicas 20:15","verse_text":"E disse: Ouvi, Judá todo, e vós moradores de Jerusalém, e tu, rei Josafá. o SENHOR vos diz assim: Não temais nem vos amedronteis diante desta tão grande multidão; porque não é vossa a guerra, mas sim de Deus."},"fr":{"prompt":"Et Jachaziel dit: Soyez attentifs, tout Juda et habitants de Jérusalem, et toi, roi Josaphat! Ainsi vous parle l’Éternel: Ne craignez point et ne vous effrayez point devant cette _____ nombreuse, car ce ne sera pas vous qui combattrez, ce sera Dieu.","bible_ref":"2 Chroniques 20:15","verse_text":"Et Jachaziel dit: Soyez attentifs, tout Juda et habitants de Jérusalem, et toi, roi Josaphat! Ainsi vous parle l’Éternel: Ne craignez point et ne vous effrayez point devant cette multitude nombreuse, car ce ne sera pas vous qui combattrez, ce sera Dieu."},"en":{"prompt":"And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great _____; for the battle is not yours, but God’s.","bible_ref":"2 Chronicles 20:15","verse_text":"And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s."},"es":{"prompt":"Y dijo: Oid, Judá todo, y vosotros moradores de Jerusalem, y tú, rey Josaphat. Jehová os dice así: No temáis ni os amedrentéis delante de esta tan grande _____; porque no es vuestra la guerra, sino de Dios.","bible_ref":"2 Crónicas 20:15","verse_text":"Y dijo: Oid, Judá todo, y vosotros moradores de Jerusalem, y tú, rey Josaphat. Jehová os dice así: No temáis ni os amedrentéis delante de esta tan grande multitud; porque no es vuestra la guerra, sino de Dios."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"montanha"},"fr":{"text":"montagne"},"en":{"text":"mountain"},"es":{"text":"montaña"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"cidade"},"fr":{"text":"ville"},"en":{"text":"city"},"es":{"text":"ciudad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"tempestade"},"fr":{"text":"tempête"},"en":{"text":"storm"},"es":{"text":"tempestad"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"multidão"},"fr":{"text":"multitude"},"en":{"text":"multitude"},"es":{"text":"multitud"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-033","type":"verse","level":"medium","testament":"ot","book":"EZR","chapter":6,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"E os filhos de Israel, os sacerdotes e os levitas, e os demais dos que vieram do cativeiro, fizeram a consagração desta casa de Deus com _____.","bible_ref":"Esdras 6:16","verse_text":"E os filhos de Israel, os sacerdotes e os levitas, e os demais dos que vieram do cativeiro, fizeram a consagração desta casa de Deus com alegria."},"fr":{"prompt":"Les enfants d’Israël, les sacrificateurs et les Lévites, et le reste des fils de la captivité, firent avec _____ la dédicace de cette maison de Dieu.","bible_ref":"Esdras 6:16","verse_text":"Les enfants d’Israël, les sacrificateurs et les Lévites, et le reste des fils de la captivité, firent avec joie la dédicace de cette maison de Dieu."},"en":{"prompt":"And the children of Israel, the priests, and the Levites, and the rest of the children of the captivity, kept the dedication of this house of God with _____,","bible_ref":"Ezra 6:16","verse_text":"And the children of Israel, the priests, and the Levites, and the rest of the children of the captivity, kept the dedication of this house of God with joy,"},"es":{"prompt":"Y los hijos de Israel, los sacerdotes y los Levitas, y los demás que habían venido de la trasportación, hicieron la dedicación de esta casa de Dios con _____.","bible_ref":"Esdras 6:16","verse_text":"Y los hijos de Israel, los sacerdotes y los Levitas, y los demás que habían venido de la trasportación, hicieron la dedicación de esta casa de Dios con gozo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"alegria"},"fr":{"text":"joie"},"en":{"text":"joy"},"es":{"text":"gozo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"temor"},"fr":{"text":"crainte"},"en":{"text":"fear"},"es":{"text":"temor"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"silêncio"},"fr":{"text":"silence"},