select public.upsert_bank_question($json${"id":"hist3-medium-034","type":"verse","level":"medium","testament":"ot","book":"NEH","chapter":4,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"No lugar onde ouvirdes o som da _____, ali vos ajuntareis conosco; nosso Deus lutará por nós.","bible_ref":"Neemias 4:20","verse_text":"No lugar onde ouvirdes o som da trombeta, ali vos ajuntareis conosco; nosso Deus lutará por nós."},"fr":{"prompt":"Au son de la _____, rassemblez-vous auprès de nous, vers le lieu d’où vous l’entendrez; notre Dieu combattra pour nous.","bible_ref":"Néhémie 4:20","verse_text":"Au son de la trompette, rassemblez-vous auprès de nous, vers le lieu d’où vous l’entendrez; notre Dieu combattra pour nous."},"en":{"prompt":"In what place therefore ye hear the sound of the _____, resort ye thither unto us: our God shall fight for us.","bible_ref":"Nehemiah 4:20","verse_text":"In what place therefore ye hear the sound of the trumpet, resort ye thither unto us: our God shall fight for us."},"es":{"prompt":"En el lugar donde oyereis la voz de la _____, reuníos allí á nosotros: nuestro Dios peleará por nosotros.","bible_ref":"Nehemías 4:20","verse_text":"En el lugar donde oyereis la voz de la trompeta, reuníos allí á nosotros: nuestro Dios peleará por nosotros."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"campainha"},"fr":{"text":"cloche"},"en":{"text":"bell"},"es":{"text":"campana"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"lira"},"fr":{"text":"lyre"},"en":{"text":"lyre"},"es":{"text":"lira"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"flauta"},"fr":{"text":"flûte"},"en":{"text":"flute"},"es":{"text":"flauta"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"trombeta"},"fr":{"text":"trompette"},"en":{"text":"trumpet"},"es":{"text":"trompeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-medium-035","type":"verse","level":"medium","testament":"ot","book":"EST","chapter":4,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Porque se te calares agora, haverá alívio e libertação para os _____ de outra parte; porém tu e a casa de teu pai perecereis. E quem sabe se foi para tempo como este que chegaste a ser rainha?","bible_ref":"Ester 4:14","verse_text":"Porque se te calares agora, haverá alívio e libertação para os judeus de outra parte; porém tu e a casa de teu pai perecereis. E quem sabe se foi para tempo como este que chegaste a ser rainha?"},"fr":{"prompt":"car, si tu te tais maintenant, le secours et la délivrance surgiront d’autre part pour les _____, et toi et la maison de ton père vous périrez. Et qui sait si ce n’est pas pour un temps comme celui-ci que tu es parvenue à la royauté?","bible_ref":"Esther 4:14","verse_text":"car, si tu te tais maintenant, le secours et la délivrance surgiront d’autre part pour les Juifs, et toi et la maison de ton père vous périrez. Et qui sait si ce n’est pas pour un temps comme celui-ci que tu es parvenue à la royauté?"},"en":{"prompt":"For if thou altogether holdest thy peace at this time, then shall there enlargement and deliverance arise to the _____ from another place; but thou and thy father’s house shall be destroyed: and who knoweth whether thou art come to the kingdom for such a time as this?","bible_ref":"Esther 4:14","verse_text":"For if thou altogether holdest thy peace at this time, then shall there enlargement and deliverance arise to the Jews from another place; but thou and thy father’s house shall be destroyed: and who knoweth whether thou art come to the kingdom for such a time as this?"},"es":{"prompt":"Porque si absolutamente callares en este tiempo, respiro y libertación tendrán los _____ de otra parte; mas tú y la casa de tu padre pereceréis. ¿Y quién sabe si para esta hora te han hecho llegar al reino?","bible_ref":"Ester 4:14","verse_text":"Porque si absolutamente callares en este tiempo, respiro y libertación tendrán los Judíos de otra parte; mas tú y la casa de tu padre pereceréis. ¿Y quién sabe si para esta hora te han hecho llegar al reino?"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"persas"},"fr":{"text":"Perses"},"en":{"text":"Persians"},"es":{"text":"Persas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"medos"},"fr":{"text":"Mèdes"},"en":{"text":"Medes"},"es":{"text":"Medos"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"judeus"},"fr":{"text":"Juifs"},"en":{"text":"Jews"},"es":{"text":"Judíos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"egípcios"},"fr":{"text":"Égyptiens"},"en":{"text":"Egyptians"},"es":{"text":"Egipcios"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-001","type":"choice","level":"hard","testament":"ot","book":"1KI","chapter":6,"verse_start":38,"verse_end":38,"texts":{"pt":{"prompt":"Quantos anos levou Salomão a edificar a casa do SENHOR?","bible_ref":"1 Reis 6:38","verse_text":"E no décimo primeiro ano, no mês de Bul, que é o mês oitavo, foi acabada a casa com todas seus partes, e com todo o necessário. Edificou-a, pois, em sete anos."},"fr":{"prompt":"En combien d’années Salomon construisit-il la maison de l’Éternel ?","bible_ref":"1 Rois 6:38","verse_text":"et la onzième année, au mois de Bul, qui est le huitième mois, la maison fut achevée dans toutes ses parties et telle qu’elle devait être. Salomon la construisit dans l’espace de sept ans."},"en":{"prompt":"How many years was Solomon in building the house of the LORD?","bible_ref":"1 Kings 6:38","verse_text":"And in the eleventh year, in the month Bul, which is the eighth month, was the house finished throughout all the parts thereof, and according to all the fashion of it. So was he seven years in building it."},"es":{"prompt":"¿En cuántos años edificó Salomón la casa de Jehová?","bible_ref":"1 Reyes 6:38","verse_text":"Y en el undécimo año, en el mes de Bul, que es el mes octavo, fué acabada la casa con todas sus pertenencias, y con todo lo necesario. Edificóla pues, en siete años."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete anos"},"fr":{"text":"Sept ans"},"en":{"text":"Seven years"},"es":{"text":"Siete años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Treze anos"},"fr":{"text":"Treize ans"},"en":{"text":"Thirteen years"},"es":{"text":"Trece años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quatro anos"},"fr":{"text":"Quatre ans"},"en":{"text":"Four years"},"es":{"text":"Cuatro años"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Vinte anos"},"fr":{"text":"Vingt ans"},"en":{"text":"Twenty years"},"es":{"text":"Veinte años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-002","type":"choice","level":"hard","testament":"ot","book":"1KI","chapter":11,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quantas esposas princesas teve Salomão?","bible_ref":"1 Reis 11:3","verse_text":"E teve setecentas esposas princesas, e trezentas concubinas; e suas mulheres desviaram o coração dele."},"fr":{"prompt":"Combien de princesses Salomon eut-il pour femmes ?","bible_ref":"1 Rois 11:3","verse_text":"Il eut sept cents princesses pour femmes et trois cents concubines; et ses femmes détournèrent son cœur."},"en":{"prompt":"How many wives, princesses, did Solomon have?","bible_ref":"1 Kings 11:3","verse_text":"And he had seven hundred wives, princesses, and three hundred concubines: and his wives turned away his heart."},"es":{"prompt":"¿Cuántas mujeres reinas tuvo Salomón?","bible_ref":"1 Reyes 11:3","verse_text":"Y tuvo setecientas mujeres reinas, y trescientas concubinas; y sus mujeres torcieron su corazón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Setecentas"},"fr":{"text":"Sept cents"},"en":{"text":"Seven hundred"},"es":{"text":"Setecientas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Trezentas"},"fr":{"text":"Trois cents"},"en":{"text":"Three hundred"},"es":{"text":"Trescientas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mil"},"fr":{"text":"Mille"},"en":{"text":"A thousand"},"es":{"text":"Mil"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cem"},"fr":{"text":"Cent"},"en":{"text":"An hundred"},"es":{"text":"Cien"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-003","type":"choice","level":"hard","testament":"ot","book":"1KI","chapter":19,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Com quantas juntas de bois lavrava Eliseu quando Elias lançou sobre ele o seu manto?","bible_ref":"1 Reis 19:19","verse_text":"E partindo-se ele dali, achou a Eliseu filho de Safate, que arava com doze juntas diante de si; e ele era um dos doze trabalhadores. E passando Elias por diante dele, lançou sobre ele seu manto."},"fr":{"prompt":"Combien de paires de bœufs Élisée avait-il devant lui quand Élie jeta sur lui son manteau ?","bible_ref":"1 Rois 19:19","verse_text":"Élie partit de là, et il trouva Élisée, fils de Schaphath, qui labourait. Il y avait devant lui douze paires de bœufs, et il était avec la douzième. Élie s’approcha de lui, et il jeta sur lui son manteau."},"en":{"prompt":"With how many yoke of oxen was Elisha plowing when Elijah cast his mantle upon him?","bible_ref":"1 Kings 19:19","verse_text":"So he departed thence, and found Elisha the son of Shaphat, who was plowing with twelve yoke of oxen before him, and he with the twelfth: and Elijah passed by him, and cast his mantle upon him."},"es":{"prompt":"¿Con cuántas yuntas araba Eliseo cuando Elías echó sobre él su manto?","bible_ref":"1 Reyes 19:19","verse_text":"Y partiéndose él de allí, halló á Eliseo hijo de Saphat, que araba con doce yuntas delante de sí; y él era uno de los doce gañanes. Y pasando Elías por delante de él, echó sobre él su manto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Duas"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-004","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Como ficou doente o rei Acazias, em Samaria?","bible_ref":"2 Reis 1:2","verse_text":"E Acazias caiu pela sacada de uma sala da casa que tinha em Samaria; e estando enfermo enviou mensageiros, e disse-lhes: Ide, e consultai a Baal-Zebube deus de Ecrom, se sararei desta minha enfermidade."},"fr":{"prompt":"Comment le roi Achazia tomba-t-il malade à Samarie ?","bible_ref":"2 Rois 1:2","verse_text":"Or Achazia tomba par le treillis de sa chambre haute à Samarie, et il en fut malade. Il fit partir des messagers, et leur dit: Allez, consultez Baal-Zebub, dieu d’Ékron, pour savoir si je guérirai de cette maladie."},"en":{"prompt":"How did king Ahaziah become sick in Samaria?","bible_ref":"2 Kings 1:2","verse_text":"And Ahaziah fell down through a lattice in his upper chamber that was in Samaria, and was sick: and he sent messengers, and said unto them, Go, enquire of Baal-zebub the god of Ekron whether I shall recover of this disease."},"es":{"prompt":"¿Cómo enfermó el rey Ochôzías en Samaria?","bible_ref":"2 Reyes 1:2","verse_text":"Y Ochôzías cayó por las celosías de una sala de la casa que tenía en Samaria; y estando enfermo envió mensajeros, y díjoles: Id, y consultad á Baal-zebub dios de Ecrón, si tengo de sanar de esta mi enfermedad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Caiu pela sacada de uma sala da sua casa"},"fr":{"text":"Il tomba par le treillis de sa chambre haute"},"en":{"text":"He fell down through a lattice in his upper chamber"},"es":{"text":"Cayó por las celosías de una sala de su casa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Foi ferido por uma flecha"},"fr":{"text":"Il fut blessé par une flèche"},"en":{"text":"He was wounded by an arrow"},"es":{"text":"Fue herido por una flecha"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Foi mordido por uma serpente"},"fr":{"text":"Il fut mordu par un serpent"},"en":{"text":"He was bitten by a serpent"},"es":{"text":"Fue mordido por una serpiente"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Caiu do cavalo"},"fr":{"text":"Il tomba de cheval"},"en":{"text":"He fell from his horse"},"es":{"text":"Cayó del caballo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-005","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":4,"verse_start":41,"verse_end":41,"texts":{"pt":{"prompt":"Quando houve mal na panela do guisado, o que deitou Eliseu nela para o tirar?","bible_ref":"2 Reis 4:41","verse_text":"Ele então disse: Trazei farinha. E espalhou-a na caçarola, e disse: Dá de comer à gente. E não houve mais mal na caçarola."},"fr":{"prompt":"Quand il y eut du mal dans le pot, qu’est-ce qu’Élisée y jeta ?","bible_ref":"2 Rois 4:41","verse_text":"Élisée dit: Prenez de la farine. Il en jeta dans le pot, et dit: Sers à ces gens, et qu’ils mangent. Et il n’y avait plus rien de mauvais dans le pot."},"en":{"prompt":"When there was harm in the pot of pottage, what did Elisha cast into it?","bible_ref":"2 Kings 4:41","verse_text":"But he said, Then bring meal. And he cast it into the pot; and he said, Pour out for the people, that they may eat. And there was no harm in the pot."},"es":{"prompt":"Cuando hubo mal en la olla del guisado, ¿qué echó Eliseo en ella para quitarlo?","bible_ref":"2 Reyes 4:41","verse_text":"El entonces dijo: Traed harina. Y esparcióla en la olla, y dijo: Echa de comer á la gente. Y no hubo más mal en la olla."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Farinha"},"fr":{"text":"De la farine"},"en":{"text":"Meal"},"es":{"text":"Harina"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sal"},"fr":{"text":"Du sel"},"en":{"text":"Salt"},"es":{"text":"Sal"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Azeite"},"fr":{"text":"De l’huile"},"en":{"text":"Oil"},"es":{"text":"Aceite"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mel"},"fr":{"text":"Du miel"},"en":{"text":"Honey"},"es":{"text":"Miel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-006","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":25,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Depois de degolarem os filhos de Zedequias diante dele, o que lhe fizeram?","bible_ref":"2 Reis 25:7","verse_text":"E degolaram aos filhos de Zedequias em sua presença; e a Zedequias tiraram os olhos, e acorrentado com correntes levaram-no à Babilônia."},"fr":{"prompt":"Après avoir égorgé les fils de Sédécias en sa présence, que lui fit-on ?","bible_ref":"2 Rois 25:7","verse_text":"Les fils de Sédécias furent égorgés en sa présence; puis on creva les yeux à Sédécias, on le lia avec des chaînes d’airain, et on le mena à Babylone."},"en":{"prompt":"After they slew the sons of Zedekiah before his eyes, what did they do to him?","bible_ref":"2 Kings 25:7","verse_text":"And they slew the sons of Zedekiah before his eyes, and put out the eyes of Zedekiah, and bound him with fetters of brass, and carried him to Babylon."},"es":{"prompt":"Después de degollar a los hijos de Sedecías en su presencia, ¿qué le hicieron?","bible_ref":"2 Reyes 25:7","verse_text":"Y degollaron á los hijos de Sedecías en presencia suya; y á Sedecías sacaron los ojos, y atado con cadenas lleváronlo á Babilonia."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tiraram-lhe os olhos"},"fr":{"text":"On lui creva les yeux"},"en":{"text":"They put out his eyes"},"es":{"text":"Le sacaron los ojos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cortaram-lhe as mãos"},"fr":{"text":"On lui coupa les mains"},"en":{"text":"They cut off his hands"},"es":{"text":"Le cortaron las manos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rasparam-lhe a cabeça"},"fr":{"text":"On lui rasa la tête"},"en":{"text":"They shaved his head"},"es":{"text":"Le raparon la cabeza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Deixaram-no em Jerusalém"},"fr":{"text":"On le laissa à Jérusalem"},"en":{"text":"They left him in Jerusalem"},"es":{"text":"Lo dejaron en Jerusalem"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-007","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":22,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"A que profetisa foram o sacerdote Hilquias e os outros falar sobre o livro?","bible_ref":"2 Reis 22:14","verse_text":"Então foi Hilquias o sacerdote, e Aicã e Acbor e Safã e Asaías, a Hulda profetisa, mulher de Salum filho de Ticvá filho de Harás, guarda das vestiduras, a qual morava em Jerusalém na segunda parte da cidade, e falaram com ela."},"fr":{"prompt":"Auprès de quelle prophétesse allèrent le sacrificateur Hilkija et les autres ?","bible_ref":"2 Rois 22:14","verse_text":"Le sacrificateur Hilkija, Achikam, Acbor, Schaphan et Asaja, allèrent auprès de la prophétesse Hulda, femme de Schallum, fils de Thikva, fils de Harhas, gardien des vêtements. Elle habitait à Jérusalem, dans l’autre quartier de la ville."},"en":{"prompt":"To which prophetess did Hilkiah the priest and the others go?","bible_ref":"2 Kings 22:14","verse_text":"So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asahiah, went unto Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe; (now she dwelt in Jerusalem in the college;) and they communed with her."},"es":{"prompt":"¿A qué profetisa fueron el sacerdote Hilcías y los demás?","bible_ref":"2 Reyes 22:14","verse_text":"Entonces fué Hilcías el sacerdote, y Ahicam y Achbor y Saphán y Asaía, á Hulda profetisa, mujer de Sallum hijo de Ticva hijo de Araas, guarda de las vestiduras, la cual moraba en Jerusalem en la segunda parte de la ciudad, y hablaron con ella."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Hulda"},"fr":{"text":"Hulda"},"en":{"text":"Huldah"},"es":{"text":"Hulda"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Débora"},"fr":{"text":"Débora"},"en":{"text":"Deborah"},"es":{"text":"Débora"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Miriã"},"fr":{"text":"Marie"},"en":{"text":"Miriam"},"es":{"text":"María"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Noadia"},"fr":{"text":"Noadia"},"en":{"text":"Noadiah"},"es":{"text":"Noadías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-008","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":1,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Como descreveram os mensageiros o homem que lhes saiu ao encontro, e que era Elias?","bible_ref":"2 Reis 1:8","verse_text":"E eles lhe responderam: Um homem vestido de pelos, e cingia seus lombos com um cinto de couro. Então ele disse: É Elias, o tisbita."},"fr":{"prompt":"Comment les messagers décrivirent-ils l’homme venu à leur rencontre, qui était Élie ?","bible_ref":"2 Rois 1:8","verse_text":"Ils lui répondirent: C’était un homme vêtu de poil et ayant une ceinture de cuir autour des reins. Et Achazia dit: C’est Élie, le Thischbite."},"en":{"prompt":"How did the messengers describe the man who met them, who was Elijah?","bible_ref":"2 Kings 1:8","verse_text":"And they answered him, He was an hairy man, and girt with a girdle of leather about his loins. And he said, It is Elijah the Tishbite."},"es":{"prompt":"¿Cómo describieron los mensajeros al hombre que les salió al encuentro, que era Elías?","bible_ref":"2 Reyes 1:8","verse_text":"Y ellos le respondieron: Un varón velloso, y ceñía sus lomos con un cinto de cuero. Entonces él dijo: Elías Thisbita es."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vestido de pelos, com um cinto de couro"},"fr":{"text":"Vêtu de poil, avec une ceinture de cuir"},"en":{"text":"An hairy man, girt with a girdle of leather"},"es":{"text":"Velloso, ceñido con un cinto de cuero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vestido de púrpura, com uma coroa"},"fr":{"text":"Vêtu de pourpre, avec une couronne"},"en":{"text":"Clothed in purple, with a crown"},"es":{"text":"Vestido de púrpura, con una corona"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um jovem com um cajado"},"fr":{"text":"Un jeune homme avec un bâton"},"en":{"text":"A young man with a staff"},"es":{"text":"Un joven con un báculo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um homem calvo, vestido de linho"},"fr":{"text":"Un homme chauve, vêtu de lin"},"en":{"text":"A bald man clothed in linen"},"es":{"text":"Un hombre calvo, vestido de lino"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-009","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":7,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quantos homens leprosos estavam à entrada da porta?","bible_ref":"2 Reis 7:3","verse_text":"E havia quatro homens leprosos à entrada da porta, os quais disseram o um ao outro: Para que nos estamos aqui até que morramos?"},"fr":{"prompt":"Combien de lépreux y avait-il à l’entrée de la porte ?","bible_ref":"2 Rois 7:3","verse_text":"Il y avait à l’entrée de la porte quatre lépreux, qui se dirent l’un à l’autre: Quoi! Resterons-nous ici jusqu’à ce que nous mourions?"},"en":{"prompt":"How many leprous men were at the entering in of the gate?","bible_ref":"2 Kings 7:3","verse_text":"And there were four leprous men at the entering in of the gate: and they said one to another, Why sit we here until we die?"},"es":{"prompt":"¿Cuántos hombres leprosos había a la entrada de la puerta?","bible_ref":"2 Reyes 7:3","verse_text":"Y había cuatro hombres leprosos á la entrada de la puerta, los cuales dijeron el uno al otro: ¿Para qué nos estamos aquí hasta que muramos?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quatro"},"fr":{"text":"Quatre"},"en":{"text":"Four"},"es":{"text":"Cuatro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dois"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-010","type":"choice","level":"hard","testament":"ot","book":"1CH","chapter":21,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo 1 Crónicas 21, quem se levantou contra Israel e incitou David a contar Israel?","bible_ref":"1 Crónicas 21:1","verse_text":"Mas Satanás se levantou contra Israel, e incitou a Davi a que contasse a Israel."},"fr":{"prompt":"Selon 1 Chroniques 21, qui se leva contre Israël et excita David à faire le dénombrement ?","bible_ref":"1 Chroniques 21:1","verse_text":"Satan se leva contre Israël, et il excita David à faire le dénombrement d’Israël."},"en":{"prompt":"According to 1 Chronicles 21, who stood up against Israel and provoked David to number Israel?","bible_ref":"1 Chronicles 21:1","verse_text":"And Satan stood up against Israel, and provoked David to number Israel."},"es":{"prompt":"Según 1 Crónicas 21, ¿quién se levantó contra Israel e incitó a David a contar a Israel?","bible_ref":"1 Crónicas 21:1","verse_text":"Mas Satanás se levantó contra Israel, é incitó á David á que contase á Israel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Satanás"},"fr":{"text":"Satan"},"en":{"text":"Satan"},"es":{"text":"Satanás"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Joabe"},"fr":{"text":"Joab"},"en":{"text":"Joab"},"es":{"text":"Joab"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Gade, o vidente"},"fr":{"text":"Gad, le voyant"},"en":{"text":"Gad the seer"},"es":{"text":"Gad el vidente"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Natã"},"fr":{"text":"Nathan"},"en":{"text":"Nathan"},"es":{"text":"Nathán"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-011","type":"choice","level":"hard","testament":"ot","book":"1CH","chapter":12,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"Os homens de que tribo conheciam os tempos, para saberem o que Israel devia fazer?","bible_ref":"1 Crónicas 12:32","verse_text":"Dos filhos de Issacar, conhecedores dos tempos, para saberem o que Israel devia fazer, duzentos de seus líderes; e todos os seus irmãos seguiam suas ordens."},"fr":{"prompt":"Les hommes de quelle tribu avaient l’intelligence des temps pour savoir ce que devait faire Israël ?","bible_ref":"1 Chroniques 12:32","verse_text":"Des fils d’Issacar, ayant l’intelligence des temps pour savoir ce que devait faire Israël, deux cents chefs, et tous leurs frères sous leurs ordres."},"en":{"prompt":"The men of which tribe had understanding of the times, to know what Israel ought to do?","bible_ref":"1 Chronicles 12:32","verse_text":"And of the children of Issachar, which were men that had understanding of the times, to know what Israel ought to do; the heads of them were two hundred; and all their brethren were at their commandment."},"es":{"prompt":"¿Los hombres de qué tribu eran entendidos en los tiempos y sabían lo que Israel debía hacer?","bible_ref":"1 Crónicas 12:32","verse_text":"Y de los hijos de Issachâr, doscientos principales, entendidos en los tiempos, y que sabían lo que Israel debía hacer, cuyo dicho seguían todos sus hermanos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Issacar"},"fr":{"text":"Issacar"},"en":{"text":"Issachar"},"es":{"text":"Issachâr"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zebulom"},"fr":{"text":"Zabulon"},"en":{"text":"Zebulun"},"es":{"text":"Zabulón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Judá"},"fr":{"text":"Juda"},"en":{"text":"Judah"},"es":{"text":"Judá"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Benjamim"},"fr":{"text":"Benjamin"},"en":{"text":"Benjamin"},"es":{"text":"Benjamín"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-012","type":"choice","level":"hard","testament":"ot","book":"2CH","chapter":17,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"No tempo de Josafá, o que levavam consigo os que ensinavam nas cidades de Judá?","bible_ref":"2 Crónicas 17:9","verse_text":"E ensinaram em Judá, tendo consigo o livro da lei do SENHOR, e rodearam por todas as cidades de Judá ensinando ao povo."},"fr":{"prompt":"Au temps de Josaphat, qu’avaient avec eux ceux qui enseignaient dans les villes de Juda ?","bible_ref":"2 Chroniques 17:9","verse_text":"Ils enseignèrent dans Juda, ayant avec eux le livre de la loi de l’Éternel. Ils parcoururent toutes les villes de Juda, et ils enseignèrent parmi le peuple."},"en":{"prompt":"In Jehoshaphat’s days, what did those who taught in the cities of Judah have with them?","bible_ref":"2 Chronicles 17:9","verse_text":"And they taught in Judah, and had the book of the law of the LORD with them, and went about throughout all the cities of Judah, and taught the people."},"es":{"prompt":"En tiempos de Josaphat, ¿qué llevaban consigo los que enseñaban en las ciudades de Judá?","bible_ref":"2 Crónicas 17:9","verse_text":"Y enseñaron en Judá, teniendo consigo el libro de la ley de Jehová, y rodearon por todas las ciudades de Judá enseñando al pueblo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O livro da lei do SENHOR"},"fr":{"text":"Le livre de la loi de l’Éternel"},"en":{"text":"The book of the law of the LORD"},"es":{"text":"El libro de la ley de Jehová"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A arca da aliança"},"fr":{"text":"L’arche de l’alliance"},"en":{"text":"The ark of the covenant"},"es":{"text":"El arca del pacto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As tábuas de pedra"},"fr":{"text":"Les tables de pierre"},"en":{"text":"The tables of stone"},"es":{"text":"Las tablas de piedra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A vara de Moisés"},"fr":{"text":"La verge de Moïse"},"en":{"text":"The rod of Moses"},"es":{"text":"La vara de Moisés"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-013","type":"choice","level":"hard","testament":"ot","book":"2CH","chapter":32,"verse_start":30,"verse_end":30,"texts":{"pt":{"prompt":"O que fez Ezequias às águas de Giom?","bible_ref":"2 Crónicas 32:30","verse_text":"Este Ezequias tapou os mananciais das águas de Giom da parte de cima, e as fez correr abaixo ao ocidente da cidade de Davi. E foi próspero Ezequias em tudo o que fez."},"fr":{"prompt":"Que fit Ézéchias des eaux de Guihon ?","bible_ref":"2 Chroniques 32:30","verse_text":"Ce fut aussi lui, Ézéchias, qui boucha l’issue supérieure des eaux de Guihon, et les conduisit en bas vers l’occident de la cité de David. Ézéchias réussit dans toutes ses entreprises."},"en":{"prompt":"What did Hezekiah do with the waters of Gihon?","bible_ref":"2 Chronicles 32:30","verse_text":"This same Hezekiah also stopped the upper watercourse of Gihon, and brought it straight down to the west side of the city of David. And Hezekiah prospered in all his works."},"es":{"prompt":"¿Qué hizo Ezechîas con las aguas de Gihón?","bible_ref":"2 Crónicas 32:30","verse_text":"Este Ezechîas tapó los manaderos de las aguas de Gihón la de arriba, y encaminólas abajo al occidente de la ciudad de David. Y fué prosperado Ezechîas en todo lo que hizo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tapou-as em cima e levou-as para o ocidente da cidade"},"fr":{"text":"Il boucha l’issue supérieure et les conduisit à l’occident"},"en":{"text":"He stopped the upper watercourse and brought it to the west"},"es":{"text":"Tapó los manaderos de arriba y las llevó al occidente"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Saneou-as com sal"},"fr":{"text":"Il les assainit avec du sel"},"en":{"text":"He healed them with salt"},"es":{"text":"Las sanó con sal"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Desviou-as para o mar"},"fr":{"text":"Il les détourna vers la mer"},"en":{"text":"He turned them into the sea"},"es":{"text":"Las desvió hacia el mar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Construiu sobre elas um palácio"},"fr":{"text":"Il bâtit dessus un palais"},"en":{"text":"He built a palace over them"},"es":{"text":"Edificó sobre ellas un palacio"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-014","type":"choice","level":"hard","testament":"ot","book":"2CH","chapter":35,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"De quem eram as palavras, vindas da boca de Deus, a que Josias não deu ouvidos?","bible_ref":"2 Crónicas 35:22","verse_text":"Mas Josias não voltou seu rosto dele, em vez disso disfarçou-se para dar-lhe batalha, e não atendeu às palavras de Neco, que eram da boca de Deus; e veio a dar-lhe a batalha no campo de Megido."},"fr":{"prompt":"De qui étaient les paroles, venues de la bouche de Dieu, que Josias n’écouta pas ?","bible_ref":"2 Chroniques 35:22","verse_text":"Mais Josias ne se détourna point de lui, et il se déguisa pour l’attaquer, sans écouter les paroles de Néco, qui venaient de la bouche de Dieu. Il s’avança pour combattre dans la vallée de Meguiddo."},"en":{"prompt":"Whose words, from the mouth of God, did Josiah not hearken unto?","bible_ref":"2 Chronicles 35:22","verse_text":"Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and hearkened not unto the words of Necho from the mouth of God, and came to fight in the valley of Megiddo."},"es":{"prompt":"¿De quién eran las palabras, de boca de Dios, a las que Josías no atendió?","bible_ref":"2 Crónicas 35:22","verse_text":"Mas Josías no volvió su rostro de él, antes disfrazóse para darle batalla, y no atendió á las palabras de Nechâo, que eran de boca de Dios; y vino á darle la batalla en el campo de Megiddo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Neco"},"fr":{"text":"Néco"},"en":{"text":"Necho"},"es":{"text":"Nechâo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Senaqueribe"},"fr":{"text":"Sanchérib"},"en":{"text":"Sennacherib"},"es":{"text":"Sennachêrib"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nabucodonosor"},"fr":{"text":"Nebucadnetsar"},"en":{"text":"Nebuchadnezzar"},"es":{"text":"Nabucodonosor"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sisaque"},"fr":{"text":"Schischak"},"en":{"text":"Shishak"},"es":{"text":"Sisac"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-015","type":"choice","level":"hard","testament":"ot","book":"EZR","chapter":2,"verse_start":64,"verse_end":64,"texts":{"pt":{"prompt":"Segundo Esdras 2:64, quantas pessoas tinha toda a congregação junta?","bible_ref":"Esdras 2:64","verse_text":"Toda esta congregação junta foi quarenta e dois mil trezentos e sessenta,"},"fr":{"prompt":"Selon Esdras 2:64, de combien de personnes était l’assemblée tout entière ?","bible_ref":"Esdras 2:64","verse_text":"L’assemblée tout entière était de quarante-deux mille trois cent soixante personnes,"},"en":{"prompt":"According to Ezra 2:64, how many was the whole congregation together?","bible_ref":"Ezra 2:64","verse_text":"The whole congregation together was forty and two thousand three hundred and threescore,"},"es":{"prompt":"Según Esdras 2:64, ¿de cuántas personas era toda la congregación?","bible_ref":"Esdras 2:64","verse_text":"Toda la congregación, unida como un solo hombre, era de cuarenta y dos mil trescientos y sesenta,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"42 360"},"fr":{"text":"42 360"},"en":{"text":"42,360"},"es":{"text":"42.360"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"24 000"},"fr":{"text":"24 000"},"en":{"text":"24,000"},"es":{"text":"24.000"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"70 000"},"fr":{"text":"70 000"},"en":{"text":"70,000"},"es":{"text":"70.000"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"7 337"},"fr":{"text":"7 337"},"en":{"text":"7,337"},"es":{"text":"7.337"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-016","type":"choice","level":"hard","testament":"ot","book":"EZR","chapter":8,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Porque não pediu Esdras ao rei soldados e cavaleiros para o caminho?","bible_ref":"Esdras 8:22","verse_text":"Pois tive vergonha de pedir ao rei tropas e cavaleiros para nos defenderem do inimigo no caminho; porque tínhamos falado ao rei, dizendo: A mão de nosso Deus está para o bem sobre todos os que o buscam; mas sua força e ira está sobre todos os que o abandonam."},"fr":{"prompt":"Pourquoi Esdras ne demanda-t-il pas au roi une escorte et des cavaliers pour la route ?","bible_ref":"Esdras 8:22","verse_text":"J’aurais eu honte de demander au roi une escorte et des cavaliers pour nous protéger contre l’ennemi pendant la route, car nous avions dit au roi: La main de notre Dieu est pour leur bien sur tous ceux qui le cherchent, mais sa force et sa colère sont sur tous ceux qui l’abandonnent."},"en":{"prompt":"Why did Ezra not ask the king for soldiers and horsemen for the way?","bible_ref":"Ezra 8:22","verse_text":"For I was ashamed to require of the king a band of soldiers and horsemen to help us against the enemy in the way: because we had spoken unto the king, saying, The hand of our God is upon all them for good that seek him; but his power and his wrath is against all them that forsake him."},"es":{"prompt":"¿Por qué no pidió Esdras al rey tropa y gente de a caballo para el camino?","bible_ref":"Esdras 8:22","verse_text":"Porque tuve vergüenza de pedir al rey tropa y gente de á caballo que nos defendiesen del enemigo en el camino: porque habíamos hablado al rey, diciendo: La mano de nuestro Dios es para bien sobre todos los que le buscan; mas su fortaleza y su furor sobre todos los que le dejan."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Teve vergonha, pois dissera que Deus protege quem o busca"},"fr":{"text":"Il aurait eu honte : il avait dit que Dieu protège ceux qui le cherchent"},"en":{"text":"He was ashamed, having said God’s hand is on all that seek him"},"es":{"text":"Tuvo vergüenza, pues había dicho que Dios ampara a los que le buscan"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O rei não tinha soldados"},"fr":{"text":"Le roi n’avait pas de soldats"},"en":{"text":"The king had no soldiers"},"es":{"text":"El rey no tenía soldados"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O caminho era curto e seguro"},"fr":{"text":"La route était courte et sûre"},"en":{"text":"The way was short and safe"},"es":{"text":"El camino era corto y seguro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os levitas eram guerreiros"},"fr":{"text":"Les Lévites étaient des guerriers"},"en":{"text":"The Levites were warriors"},"es":{"text":"Los Levitas eran guerreros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-017","type":"choice","level":"hard","testament":"ot","book":"EZR","chapter":10,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quando o povo se sentou na praça da casa de Deus, o que o fazia tremer além daquele assunto?","bible_ref":"Esdras 10:9","verse_text":"Então todos os homens de Judá e de Benjamim se reuniram em Jerusalém em três dias, aos vinte do mês, no nono mês; e todo o povo se sentou na praça da casa de Deus, tremendo por causa deste negócio, e por causa das grandes chuvas."},"fr":{"prompt":"Quand le peuple se tenait sur la place de la maison de Dieu, qu’est-ce qui le faisait trembler en plus ?","bible_ref":"Esdras 10:9","verse_text":"Tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans les trois jours. C’était le vingtième jour du neuvième mois. Tout le peuple se tenait sur la place de la maison de Dieu, tremblant à cause de la circonstance et par suite de la pluie."},"en":{"prompt":"When the people sat in the street of the house of God, what besides the matter made them tremble?","bible_ref":"Ezra 10:9","verse_text":"Then all the men of Judah and Benjamin gathered themselves together unto Jerusalem within three days. It was the ninth month, on the twentieth day of the month; and all the people sat in the street of the house of God, trembling because of this matter, and for the great rain."},"es":{"prompt":"Cuando el pueblo se sentó en la plaza de la casa de Dios, ¿qué lo hacía temblar además de aquel negocio?","bible_ref":"Esdras 10:9","verse_text":"Así todos los hombres de Judá y de Benjamín se reunieron en Jerusalem dentro de tres días, á los veinte del mes, el cual era el mes noveno; y sentóse todo el pueblo en la plaza de la casa de Dios, temblando con motivo de aquel negocio, y á causa de las lluvias."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A chuva"},"fr":{"text":"La pluie"},"en":{"text":"The great rain"},"es":{"text":"Las lluvias"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um terramoto"},"fr":{"text":"Un tremblement de terre"},"en":{"text":"An earthquake"},"es":{"text":"Un terremoto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A neve"},"fr":{"text":"La neige"},"en":{"text":"The snow"},"es":{"text":"La nieve"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um exército inimigo"},"fr":{"text":"Une armée ennemie"},"en":{"text":"An enemy army"},"es":{"text":"Un ejército enemigo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-018","type":"choice","level":"hard","testament":"ot","book":"NEH","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em que mês, no vigésimo ano de Artaxerxes, levou Neemias o vinho ao rei?","bible_ref":"Neemias 2:1","verse_text":"Sucedeu, pois, no mês de Nisã, no ano vigésimo do rei Artaxerxes, que havendo vinho diante dele, tomei o vinho, e o dei ao rei. Porém eu nunca havia estado triste diante dele."},"fr":{"prompt":"En quel mois de la vingtième année d’Artaxerxès Néhémie offrit-il le vin au roi ?","bible_ref":"Néhémie 2:1","verse_text":"Au mois de Nisan, la vingtième année du roi Artaxerxès, comme le vin était devant lui, je pris le vin et je l’offris au roi. Jamais je n’avais paru triste en sa présence."},"en":{"prompt":"In which month of the twentieth year of Artaxerxes did Nehemiah give the wine to the king?","bible_ref":"Nehemiah 2:1","verse_text":"And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."},"es":{"prompt":"¿En qué mes del año veinte de Artajerjes dio Nehemías el vino al rey?","bible_ref":"Nehemías 2:1","verse_text":"Y fué en el mes de Nisán, en el año veinte del rey Artajerjes, que estando ya el vino delante de él, tomé el vino, y dílo al rey. Y como yo no había estado antes triste en su presencia,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nisã"},"fr":{"text":"Nisan"},"en":{"text":"Nisan"},"es":{"text":"Nisán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Adar"},"fr":{"text":"Adar"},"en":{"text":"Adar"},"es":{"text":"Adar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Elul"},"fr":{"text":"Élul"},"en":{"text":"Elul"},"es":{"text":"Elul"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quisleu"},"fr":{"text":"Kisleu"},"en":{"text":"Chisleu"},"es":{"text":"Chisleu"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-019","type":"choice","level":"hard","testament":"ot","book":"NEH","chapter":6,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Quando lhe propuseram que se escondesse no templo, o que respondeu Neemias?","bible_ref":"Neemias 6:11","verse_text":"Porém eu disse: Um homem como eu fugiria? E poderia alguém como eu entrar no templo para preservar sua vida? De maneira nenhuma entrarei."},"fr":{"prompt":"Quand on lui proposa de se cacher dans le temple, que répondit Néhémie ?","bible_ref":"Néhémie 6:11","verse_text":"Je répondis: Un homme comme moi prendre la fuite! Et quel homme tel que moi pourrait entrer dans le temple et vivre? Je n’entrerai point."},"en":{"prompt":"When he was urged to hide in the temple, what did Nehemiah answer?","bible_ref":"Nehemiah 6:11","verse_text":"And I said, Should such a man as I flee? and who is there, that, being as I am, would go into the temple to save his life? I will not go in."},"es":{"prompt":"Cuando le propusieron esconderse en el templo, ¿qué respondió Nehemías?","bible_ref":"Nehemías 6:11","verse_text":"Entonces dije: ¿Un hombre como yo ha de huir? ¿y quién, que como yo fuera, entraría al templo para salvar la vida? No entraré."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"«Um homem como eu fugiria?»"},"fr":{"text":"« Un homme comme moi prendre la fuite ! »"},"en":{"text":"“Should such a man as I flee?”"},"es":{"text":"«¿Un hombre como yo ha de huir?»"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"«Irei contigo e esconder-me-ei»"},"fr":{"text":"« J’irai avec toi et je me cacherai »"},"en":{"text":"“I will go with thee and hide”"},"es":{"text":"«Iré contigo y me esconderé»"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"«Pedirei soldados ao rei»"},"fr":{"text":"« Je demanderai des soldats au roi »"},"en":{"text":"“I will ask the king for soldiers”"},"es":{"text":"«Pediré soldados al rey»"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"«Esperarei pela noite»"},"fr":{"text":"« J’attendrai la nuit »"},"en":{"text":"“I will wait for the night”"},"es":{"text":"«Esperaré a la noche»"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-020","type":"choice","level":"hard","testament":"ot","book":"EST","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Sobre quantas províncias reinava Assuero?","bible_ref":"Ester 1:1","verse_text":"E aconteceu nos dias de Assuero (o Assuero que reinou desde a Índia até Cuxe sobre cento e vinte e sete províncias),"},"fr":{"prompt":"Sur combien de provinces régnait Assuérus ?","bible_ref":"Esther 1:1","verse_text":"C’était du temps d’Assuérus, de cet Assuérus qui régnait depuis l’Inde jusqu’en Éthiopie sur cent vingt-sept provinces;"},"en":{"prompt":"Over how many provinces did Ahasuerus reign?","bible_ref":"Esther 1:1","verse_text":"Now it came to pass in the days of Ahasuerus, (this is Ahasuerus which reigned, from India even unto Ethiopia, over an hundred and seven and twenty provinces:)"},"es":{"prompt":"¿Sobre cuántas provincias reinaba Assuero?","bible_ref":"Ester 1:1","verse_text":"Y aconteció en los días de Assuero, (el Assuero que reinó desde la India hasta la Etiopía sobre ciento veinte y siete provincias,)"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"127"},"fr":{"text":"127"},"en":{"text":"127"},"es":{"text":"127"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"120"},"fr":{"text":"120"},"en":{"text":"120"},"es":{"text":"120"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"100"},"fr":{"text":"100"},"en":{"text":"100"},"es":{"text":"100"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"70"},"fr":{"text":"70"},"en":{"text":"70"},"es":{"text":"70"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-021","type":"choice","level":"hard","testament":"ot","book":"EST","chapter":5,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Quem aconselhou Hamã a mandar fazer uma forca de cinquenta côvados?","bible_ref":"Ester 5:14","verse_text":"Então sua mulher Zeres e todos os seus amigos lhe disseram: Seja feita uma forca de cinquenta côvados de altura, e amanhã dize ao rei para que nela enforquem a Mardoqueu; e então vai alegre com o rei ao banquete. E este conselho foi do agrado de Hamã, e ele mandou fazer a forca."},"fr":{"prompt":"Qui conseilla à Haman de faire préparer un bois haut de cinquante coudées ?","bible_ref":"Esther 5:14","verse_text":"Zéresch, sa femme, et tous ses amis lui dirent: Qu’on prépare un bois haut de cinquante coudées, et demain matin demande au roi qu’on y pende Mardochée; puis tu iras joyeux au festin avec le roi. Cet avis plut à Haman, et il fit préparer le bois."},"en":{"prompt":"Who counselled Haman to make a gallows fifty cubits high?","bible_ref":"Esther 5:14","verse_text":"Then said Zeresh his wife and all his friends unto him, Let a gallows be made of fifty cubits high, and to morrow speak thou unto the king that Mordecai may be hanged thereon: then go thou in merrily with the king unto the banquet. And the thing pleased Haman; and he caused the gallows to be made."},"es":{"prompt":"¿Quién aconsejó a Amán hacer una horca alta de cincuenta codos?","bible_ref":"Ester 5:14","verse_text":"Y díjole Zeres su mujer, y todos sus amigos: Hagan una horca alta de cincuenta codos, y mañana di al rey que cuelguen á Mardochêo en ella; y entra con el rey al banquete alegre. Y plugo la cosa en los ojos de Amán, é hizo preparar la horca."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Zeres, sua mulher, e os seus amigos"},"fr":{"text":"Zéresch, sa femme, et tous ses amis"},"en":{"text":"Zeresh his wife and all his friends"},"es":{"text":"Zeres su mujer y todos sus amigos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O rei Assuero"},"fr":{"text":"Le roi Assuérus"},"en":{"text":"King Ahasuerus"},"es":{"text":"El rey Assuero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os eunucos da porta"},"fr":{"text":"Les eunuques de la porte"},"en":{"text":"The chamberlains of the gate"},"es":{"text":"Los eunucos de la puerta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A rainha Vasti"},"fr":{"text":"La reine Vasthi"},"en":{"text":"Queen Vashti"},"es":{"text":"La reina Vasthi"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-022","type":"order","level":"hard","testament":"ot","book":"1KI","chapter":12,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"1 Reis 12:1","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"1 Rois 12:1","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"1 Kings 12:1","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"1 Reyes 12:1","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Roboão vai a Siquém para ser feito rei","ref":"1 Reis 12:1"},"fr":{"text":"Roboam se rend à Sichem pour être fait roi","ref":"1 Rois 12:1"},"en":{"text":"Rehoboam goes to Shechem to be made king","ref":"1 Kings 12:1"},"es":{"text":"Roboam va a Sichêm para ser hecho rey","ref":"1 Reyes 12:1"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O povo pede-lhe que alivie o jugo pesado","ref":"1 Reis 12:4"},"fr":{"text":"Le peuple lui demande d’alléger le joug pesant","ref":"1 Rois 12:4"},"en":{"text":"The people ask him to lighten the heavy yoke","ref":"1 Kings 12:4"},"es":{"text":"El pueblo le pide que alivie el yugo pesado","ref":"1 Reyes 12:4"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Roboão responde duramente e deixa o conselho dos anciãos","ref":"1 Reis 12:13"},"fr":{"text":"Roboam répond durement et laisse le conseil des vieillards","ref":"1 Rois 12:13"},"en":{"text":"Rehoboam answers roughly, forsaking the old men’s counsel","ref":"1 Kings 12:13"},"es":{"text":"Roboam responde duramente y deja el consejo de los ancianos","ref":"1 Reyes 12:13"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Adorão é apedrejado e Roboão foge para Jerusalém","ref":"1 Reis 12:18"},"fr":{"text":"Adoram est lapidé et Roboam s’enfuit à Jérusalem","ref":"1 Rois 12:18"},"en"