select public.upsert_bank_question($json${"id":"hist3-hard-023","type":"order","level":"hard","testament":"ot","book":"2KI","chapter":9,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"2 Reis 9:20","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"2 Rois 9:20","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"2 Kings 9:20","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"2 Reyes 9:20","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"O atalaia reconhece o marchar impetuoso de Jeú","ref":"2 Reis 9:20"},"fr":{"text":"La sentinelle reconnaît la conduite de Jéhu","ref":"2 Rois 9:20"},"en":{"text":"The watchman sees Jehu driving furiously","ref":"2 Kings 9:20"},"es":{"text":"El atalaya reconoce el marchar de Jehú","ref":"2 Reyes 9:20"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jeú fere Jorão com uma flecha","ref":"2 Reis 9:24"},"fr":{"text":"Jéhu frappe Joram d’une flèche","ref":"2 Rois 9:24"},"en":{"text":"Jehu smites Jehoram with an arrow","ref":"2 Kings 9:24"},"es":{"text":"Jehú hiere a Joram con una saeta","ref":"2 Reyes 9:24"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jezabel é lançada abaixo","ref":"2 Reis 9:33"},"fr":{"text":"Jézabel est jetée en bas","ref":"2 Rois 9:33"},"en":{"text":"Jezebel is thrown down","ref":"2 Kings 9:33"},"es":{"text":"Jezabel es echada abajo","ref":"2 Reyes 9:33"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A casa de Baal é derrubada","ref":"2 Reis 10:27"},"fr":{"text":"La maison de Baal est renversée","ref":"2 Rois 10:27"},"en":{"text":"The house of Baal is broken down","ref":"2 Kings 10:27"},"es":{"text":"La casa de Baal es derribada","ref":"2 Reyes 10:27"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-024","type":"order","level":"hard","testament":"ot","book":"2KI","chapter":24,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"2 Reis 24:15","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"2 Rois 24:15","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"2 Kings 24:15","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"2 Reyes 24:15","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Joaquim é levado cativo para Babilónia","ref":"2 Reis 24:15"},"fr":{"text":"Jojakin est transporté à Babylone","ref":"2 Rois 24:15"},"en":{"text":"Jehoiachin is carried away to Babylon","ref":"2 Kings 24:15"},"es":{"text":"Joachîn es trasportado a Babilonia","ref":"2 Reyes 24:15"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Matanias é feito rei com o nome de Zedequias","ref":"2 Reis 24:17"},"fr":{"text":"Matthania devient roi sous le nom de Sédécias","ref":"2 Rois 24:17"},"en":{"text":"Mattaniah is made king and named Zedekiah","ref":"2 Kings 24:17"},"es":{"text":"Mathanías es hecho rey con el nombre de Sedecías","ref":"2 Reyes 24:17"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A cidade é aberta e os homens de guerra fogem de noite","ref":"2 Reis 25:4"},"fr":{"text":"La brèche est faite et les gens de guerre fuient de nuit","ref":"2 Rois 25:4"},"en":{"text":"The city is broken up; the men of war flee by night","ref":"2 Kings 25:4"},"es":{"text":"Abierta la ciudad, los hombres de guerra huyen de noche","ref":"2 Reyes 25:4"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A casa do SENHOR é queimada","ref":"2 Reis 25:9"},"fr":{"text":"La maison de l’Éternel est brûlée","ref":"2 Rois 25:9"},"en":{"text":"The house of the LORD is burnt","ref":"2 Kings 25:9"},"es":{"text":"La casa de Jehová es quemada","ref":"2 Reyes 25:9"}}}]}$json$::jsonb);
