select public.upsert_bank_question($json${"id":"hist3-hard-028","type":"order","level":"hard","testament":"ot","book":"EST","chapter":3,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Ester 3:1","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Esther 3:1","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Esther 3:1","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Ester 3:1","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Assuero engrandece Hamã acima de todos os príncipes","ref":"Ester 3:1"},"fr":{"text":"Assuérus élève Haman au-dessus de tous les chefs","ref":"Esther 3:1"},"en":{"text":"Ahasuerus promotes Haman above all the princes","ref":"Esther 3:1"},"es":{"text":"Assuero engrandece a Amán sobre todos los príncipes","ref":"Ester 3:1"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os escrivães do rei escrevem as ordens de Hamã","ref":"Ester 3:12"},"fr":{"text":"Les secrétaires du roi écrivent les ordres d’Haman","ref":"Esther 3:12"},"en":{"text":"The king’s scribes write all that Haman commanded","ref":"Esther 3:12"},"es":{"text":"Los escribanos del rey escriben lo que mandó Amán","ref":"Ester 3:12"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O rei dá a Mardoqueu o anel tirado a Hamã","ref":"Ester 8:2"},"fr":{"text":"Le roi donne à Mardochée l’anneau repris à Haman","ref":"Esther 8:2"},"en":{"text":"The king gives Mordecai the ring taken from Haman","ref":"Esther 8:2"},"es":{"text":"El rey da a Mardochêo el anillo quitado a Amán","ref":"Ester 8:2"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os dez filhos de Hamã são enforcados","ref":"Ester 9:14"},"fr":{"text":"Les dix fils d’Haman sont pendus","ref":"Esther 9:14"},"en":{"text":"Haman’s ten sons are hanged","ref":"Esth