select public.upsert_bank_question($json${"id":"hist3-hard-029","type":"verse","level":"hard","testament":"ot","book":"1KI","chapter":8,"verse_start":56,"verse_end":56,"texts":{"pt":{"prompt":"Bendito seja o SENHOR, que deu _____ ao seu povo Israel, conforme a tudo o que disse; nenhuma palavra falhou de todas as suas boas promessas que falou por meio de seu servo Moisés.","bible_ref":"1 Reis 8:56","verse_text":"Bendito seja o SENHOR, que deu repouso ao seu povo Israel, conforme a tudo o que disse; nenhuma palavra falhou de todas as suas boas promessas que falou por meio de seu servo Moisés."},"fr":{"prompt":"Béni soit l’Éternel, qui a donné du _____ à son peuple d’Israël, selon toutes ses promesses! De toutes les bonnes paroles qu’il avait prononcées par Moïse, son serviteur, aucune n’est restée sans effet.","bible_ref":"1 Rois 8:56","verse_text":"Béni soit l’Éternel, qui a donné du repos à son peuple d’Israël, selon toutes ses promesses! De toutes les bonnes paroles qu’il avait prononcées par Moïse, son serviteur, aucune n’est restée sans effet."},"en":{"prompt":"Blessed be the LORD, that hath given _____ unto his people Israel, according to all that he promised: there hath not failed one word of all his good promise, which he promised by the hand of Moses his servant.","bible_ref":"1 Kings 8:56","verse_text":"Blessed be the LORD, that hath given rest unto his people Israel, according to all that he promised: there hath not failed one word of all his good promise, which he promised by the hand of Moses his servant."},"es":{"prompt":"Bendito sea Jehová, que ha dado _____ á su pueblo Israel, conforme á todo lo que él había dicho; ninguna palabra de todas sus promesas que expresó por Moisés su siervo, ha faltado.","bible_ref":"1 Reyes 8:56","verse_text":"Bendito sea Jehová, que ha dado reposo á su pueblo Israel, conforme á todo lo que él había dicho; ninguna palabra de todas sus promesas que expresó por Moisés su siervo, ha faltado."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"vinho"},"fr":{"text":"vin"},"en":{"text":"wine"},"es":{"text":"vino"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"pão"},"fr":{"text":"pain"},"en":{"text":"bread"},"es":{"text":"pan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"despojo"},"fr":{"text":"butin"},"en":{"text":"spoil"},"es":{"text":"despojo"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"repouso"},"fr":{"text":"repos"},"en":{"text":"rest"},"es":{"text":"reposo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-030","type":"verse","level":"hard","testament":"ot","book":"2KI","chapter":23,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"Não houve tal rei antes dele que se convertesse ao SENHOR de todo seu coração, e de toda sua alma, e de todas suas _____, conforme a toda a lei de Moisés; nem depois dele nasceu outro tal.","bible_ref":"2 Reis 23:25","verse_text":"Não houve tal rei antes dele que se convertesse ao SENHOR de todo seu coração, e de toda sua alma, e de todas suas forças, conforme a toda a lei de Moisés; nem depois dele nasceu outro tal."},"fr":{"prompt":"Avant Josias, il n’y eut point de roi qui, comme lui, revînt à l’Éternel de tout son cœur, de toute son âme et de toute sa _____, selon toute la loi de Moïse; et après lui, il n’en a point paru de semblable.","bible_ref":"2 Rois 23:25","verse_text":"Avant Josias, il n’y eut point de roi qui, comme lui, revînt à l’Éternel de tout son cœur, de toute son âme et de toute sa force, selon toute la loi de Moïse; et après lui, il n’en a point paru de semblable."},"en":{"prompt":"And like unto him was there no king before him, that turned to the LORD with all his heart, and with all his soul, and with all his _____, according to all the law of Moses; neither after him arose there any like him.","bible_ref":"2 Kings 23:25","verse_text":"And like unto him was there no king before him, that turned to the LORD with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him."},"es":{"prompt":"No hubo tal rey antes de él que se convirtiese á Jehová de todo su corazón, y de toda su alma, y de todas sus _____, conforme á toda la ley de Moisés; ni después de él nació otro tal.","bible_ref":"2 Reyes 23:25","verse_text":"No hubo tal rey antes de él que se convirtiese á Jehová de todo su corazón, y de toda su alma, y de todas sus fuerzas, conforme á toda la ley de Moisés; ni después de él nació otro tal."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"palavras"},"fr":{"text":"parole"},"en":{"text":"words"},"es":{"text":"palabras"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"obras"},"fr":{"text":"œuvre"},"en":{"text":"works"},"es":{"text":"obras"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"riquezas"},"fr":{"text":"richesse"},"en":{"text":"riches"},"es":{"text":"riquezas"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"forças"},"fr":{"text":"force"},"en":{"text":"might"},"es":{"text":"fuerzas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-031","type":"verse","level":"hard","testament":"ot","book":"1CH","chapter":29,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Porque nós, estrangeiros e peregrinos somos diante de ti, como todos nossos pais; e nossos dias qual _____ sobre a terra, e não dão espera.","bible_ref":"1 Crónicas 29:15","verse_text":"Porque nós, estrangeiros e peregrinos somos diante de ti, como todos nossos pais; e nossos dias qual sombra sobre a terra, e não dão espera."},"fr":{"prompt":"Nous sommes devant toi des étrangers et des habitants, comme tous nos pères; nos jours sur la terre sont comme l’_____, et il n’y a point d’espérance.","bible_ref":"1 Chroniques 29:15","verse_text":"Nous sommes devant toi des étrangers et des habitants, comme tous nos pères; nos jours sur la terre sont comme l’ombre, et il n’y a point d’espérance."},"en":{"prompt":"For we are strangers before thee, and sojourners, as were all our fathers: our days on the earth are as a _____, and there is none abiding.","bible_ref":"1 Chronicles 29:15","verse_text":"For we are strangers before thee, and sojourners, as were all our fathers: our days on the earth are as a shadow, and there is none abiding."},"es":{"prompt":"Porque nosotros, extranjeros y advenedizos somos delante de ti, como todos nuestros padres; y nuestros días cual _____ sobre la tierra, y no dan espera.","bible_ref":"1 Crónicas 29:15","verse_text":"Porque nosotros, extranjeros y advenedizos somos delante de ti, como todos nuestros padres; y nuestros días cual sombra sobre la tierra, y no dan espera."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"tempestade"},"fr":{"text":"orage"},"en":{"text":"storm"},"es":{"text":"tormenta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"faísca"},"fr":{"text":"étincelle"},"en":{"text":"spark"},"es":{"text":"chispa"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"sombra"},"fr":{"text":"ombre"},"en":{"text":"s