select public.upsert_bank_question($json${"id":"hist3-hard-032","type":"verse","level":"hard","testament":"ot","book":"2CH","chapter":15,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Esforçai-vos, porém, vós, e não desfaleçam vossas _____; que recompensa há para vossa obra.","bible_ref":"2 Crónicas 15:7","verse_text":"Esforçai-vos, porém, vós, e não desfaleçam vossas mãos; que recompensa há para vossa obra."},"fr":{"prompt":"Vous donc, fortifiez-vous, et ne laissez pas vos _____ s’affaiblir, car il y aura un salaire pour vos œuvres.","bible_ref":"2 Chroniques 15:7","verse_text":"Vous donc, fortifiez-vous, et ne laissez pas vos mains s’affaiblir, car il y aura un salaire pour vos œuvres."},"en":{"prompt":"Be ye strong therefore, and let not your _____ be weak: for your work shall be rewarded.","bible_ref":"2 Chronicles 15:7","verse_text":"Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded."},"es":{"prompt":"Esforzaos empero vosotros, y no desfallezcan vuestras _____; que salario hay para vuestra obra.","bible_ref":"2 Crónicas 15:7","verse_text":"Esforzaos empero vosotros, y no desfallezcan vuestras manos; que salario hay para vuestra obra."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"almas"},"fr":{"text":"âmes"},"en":{"text":"souls"},"es":{"text":"almas"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"mãos"},"fr":{"text":"mains"},"en":{"text":"hands"},"es":{"text":"manos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"pernas"},"fr":{"text":"jambes"},"en":{"text":"legs"},"es":{"text":"piernas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"vozes"},"fr":{"text":"voix"},"en":{"text":"voices"},"es":{"text":"voces"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist3-hard-033","type":"verse","level":"hard","testament":"ot","book":"2CH","chapter":32,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Com ele está a força da _____, mas conosco está o SENHOR nosso Deus para ajudar-nos, e lutar nossas batalhas. E firmou-se o povo sobre as palavras de Ezequias rei de Judá.","bible_ref":"2 Crónicas 32:8","verse_text":"Com ele está a força da carne, mas conosco está o SENHOR nosso Deus para ajudar-nos, e lutar nossas batalhas. E firmou-se o povo sobre as palavras de Ezequias rei de Judá."},"fr":{"prompt":"Avec lui est un bras de _____, et avec nous l’Éternel, notre Dieu, qui nous aidera et qui combattra pour nous. Le peuple eut confiance dans les paroles d’Ézéchias, roi de Juda.","bible_ref":"2 Chroniques 32:8","verse_text":"Avec lui est un bras de chair, et avec nous l’Éternel, notre Dieu, qui nous aidera et qui combattra pour nous. Le peuple eut confiance dans les paroles d’Ézéchias, roi de Juda."},"en":{"prompt":"With him is an arm of _____; but with us is the LORD our God to help us, and to fight our battles. And the people rested themselves upon the words of Hezekiah king of Judah.","bible_ref":"2 Chronicles 32:8","verse_text":"With him is an arm of flesh; but with us is the LORD our God to help us, and to fight our battles. And the people rested themselves upon the words of Hezekiah king of Judah."},"es":{"prompt":"Con él es el brazo de _____, mas con nosotros Jehová nuestro Dios para ayudarnos, y pelear nuestras batallas. Y afirmóse el pueblo sobre las palabras de Ezechîas rey de Judá.","bible_ref":"2 Crónicas 32:8","verse_text":"Con él es el brazo de carne, mas con nosotros Jehová nuestro Dios para ayudarnos, y pelear nuestras batallas. Y afirmóse el pueblo sobre las palabras de Ezechîas rey de Judá."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"carne"},"fr":{"text":"chair"},"en":{"text":"flesh"},"es":{"text":"carne"}}},{"position":2,"is_correct":fa